/* Reused mantra texts */
const M_ACAMANA = `ॐ अच्युताय नमः । ॐ अनन्ताय नमः । ॐ गोविन्दाय नमः ॥`;
const M_PRANAYAMA = `ॐ भूः । ॐ भुवः । ओग्ं सुवः । ॐ महः । ॐ जनः । ॐ तपः । ओग्ं सत्यम् ।
ॐ तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ।
ओमापो ज्योती रसोऽमृतं ब्रह्म भूर्भुवस्सुवरोम् ॥`;
const M_APOHISHTA = `आपो हि ष्ठा मयोभुवः । ता न ऊर्जे दधातन । महे रणाय चक्षसे ।
यो वश्शिवतमो रसः । तस्य भाजयतेह नः । उशतीरिव मातरः ।
तस्मा अरङ्गमाम वः । यस्य क्षयाय जिन्वथ । आपो जनयथा च नः ॥
ॐ भूर्भुवस्सुवः ॥`;
const M_GAYATRI = `ॐ भूर्भुवस्सुवः । तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ॥`;
const SK = `ममोपात्त समस्त दुरितक्षयद्वारा श्रीपरमेश्वरप्रीत्यर्थं `;

const MEAN_GAYATRI = L(
  `Om. Earth, atmosphere, heaven. We meditate on that adorable radiance of the divine Savitṛ, the Sun. May he inspire our intellect.`,
  `ಓಂ. ಭೂಮಿ, ಅಂತರಿಕ್ಷ, ಸ್ವರ್ಗ. ಸವಿತೃ ದೇವನ ವರೇಣ್ಯವಾದ ತೇಜಸ್ಸನ್ನು ಧ್ಯಾನಿಸುತ್ತೇವೆ. ಅವನು ನಮ್ಮ ಬುದ್ಧಿಯನ್ನು ಪ್ರೇರೇಪಿಸಲಿ.`,
  `ఓం. భూమి, అంతరిక్షం, స్వర్గం. సవితృ దేవుని వరేణ్యమైన తేజస్సును ధ్యానిస్తున్నాము. ఆయన మా బుద్ధిని ప్రేరేపించుగాక.`,
  `ஓம். பூமி, அந்தரிக்ஷம், சுவர்க்கம். ஸவித்ரு தேவனின் போற்றத்தக்க ஒளியைத் தியானிக்கிறோம். அவன் எங்கள் அறிவைத் தூண்டட்டும்.`,
  `ॐ। भूलोक, अन्तरिक्ष, स्वर्ग। हम सविता देव के वरणीय तेज का ध्यान करते हैं। वे हमारी बुद्धि को प्रेरित करें।`);

const VD_STEPS = [
  { id:'prep', t:`पूर्वसिद्धता`, ash:'do',
    how: L(`Bathe, wear a clean dhoti in pañcakaccha style and keep the yajñopavīta over the left shoulder. Apply bhasma or tilaka. Sit on a clean seat with a vessel (pañcapātra) of water and a spoon (uddhariṇi).`,
      `ಸ್ನಾನ ಮಾಡಿ, ಶುಭ್ರವಾದ ಪಂಚೆಯನ್ನು ಪಂಚಕಚ್ಚೆಯಾಗಿ ಉಟ್ಟು, ಯಜ್ಞೋಪವೀತ ಎಡ ಹೆಗಲಿನ ಮೇಲಿರಲಿ. ಭಸ್ಮ ಅಥವಾ ತಿಲಕ ಧರಿಸಿ. ಪಂಚಪಾತ್ರೆಯಲ್ಲಿ ನೀರು ಮತ್ತು ಉದ್ಧರಣೆಯೊಂದಿಗೆ ಶುದ್ಧ ಆಸನದಲ್ಲಿ ಕುಳಿತುಕೊಳ್ಳಿ.`,
      `స్నానం చేసి, శుభ్రమైన పంచెను పంచకచ్చంగా కట్టుకొని, యజ్ఞోపవీతం ఎడమ భుజంపై ఉంచండి. భస్మం లేదా తిలకం ధరించండి. పంచపాత్రలో నీరు, ఉద్ధరిణితో శుభ్రమైన ఆసనంపై కూర్చోండి.`,
      `நீராடி, சுத்தமான வேஷ்டியைப் பஞ்சகச்சமாக அணிந்து, பூணூல் இடது தோளில் இருக்கட்டும். விபூதி அல்லது திலகம் இட்டுக்கொள்ளவும். பஞ்சபாத்திரத்தில் நீர், உத்தரணியுடன் சுத்தமான ஆசனத்தில் அமரவும்.`,
      `स्नान करके स्वच्छ धोती पञ्चकच्छ रूप में पहनें, यज्ञोपवीत बाएँ कंधे पर रहे। भस्म या तिलक लगाएँ। पञ्चपात्र में जल और उद्धरणी लेकर स्वच्छ आसन पर बैठें।`),
    howK: {
      pratah: L(`Begin while the stars are still visible, about 72 minutes before sunrise. Face east, and offer arghya before the Sun rises.`,
        `ನಕ್ಷತ್ರಗಳು ಕಾಣುತ್ತಿರುವಾಗಲೇ, ಸೂರ್ಯೋದಯಕ್ಕೆ ಸುಮಾರು 72 ನಿಮಿಷ ಮೊದಲು ಆರಂಭಿಸಿ. ಪೂರ್ವಾಭಿಮುಖವಾಗಿದ್ದು, ಸೂರ್ಯೋದಯಕ್ಕೆ ಮುನ್ನ ಅರ್ಘ್ಯ ಕೊಡಿ.`,
        `నక్షత్రాలు కనిపిస్తుండగానే, సూర్యోదయానికి సుమారు 72 నిమిషాల ముందు ప్రారంభించండి. తూర్పు ముఖంగా ఉండి, సూర్యోదయానికి ముందే అర్ఘ్యం ఇవ్వండి.`,
        `நட்சத்திரங்கள் தெரியும்போதே, சூரிய உதயத்துக்குச் சுமார் 72 நிமிடம் முன் தொடங்கவும். கிழக்கு நோக்கி, சூரியன் உதிக்கும் முன் அர்க்கியம் விடவும்.`,
        `तारे दिखते हुए ही, सूर्योदय से लगभग 72 मिनट पहले आरम्भ करें। पूर्वाभिमुख रहें और सूर्योदय से पहले अर्घ्य दें।`),
      madhya: L(`Perform at midday, within 24 minutes of solar noon. Face east (some families face north).`,
        `ಮಧ್ಯಾಹ್ನದಲ್ಲಿ, ಸೂರ್ಯನ ಮಧ್ಯಾಹ್ನದಿಂದ 24 ನಿಮಿಷಗಳೊಳಗೆ ಮಾಡಿ. ಪೂರ್ವಾಭಿಮುಖವಾಗಿರಿ (ಕೆಲವರು ಉತ್ತರಾಭಿಮುಖ).`,
        `మధ్యాహ్నం, సూర్య మధ్యాహ్నానికి 24 నిమిషాల లోపు చేయండి. తూర్పు ముఖంగా ఉండండి (కొందరు ఉత్తర ముఖంగా).`,
        `நண்பகலில், சூரிய மத்தியான நேரத்திலிருந்து 24 நிமிடத்துக்குள் செய்யவும். கிழக்கு நோக்கி (சிலர் வடக்கு நோக்கி).`,
        `मध्याह्न में, सौर मध्याह्न के 24 मिनट के भीतर करें। पूर्वाभिमुख रहें (कुछ परिवार उत्तराभिमुख)।`),
      sayam: L(`Begin before sunset and offer arghya while the Sun is still above the horizon. Face west.`,
        `ಸೂರ್ಯಾಸ್ತಕ್ಕೆ ಮೊದಲು ಆರಂಭಿಸಿ, ಸೂರ್ಯ ಕಾಣುತ್ತಿರುವಾಗಲೇ ಅರ್ಘ್ಯ ಕೊಡಿ. ಪಶ್ಚಿಮಾಭಿಮುಖವಾಗಿರಿ.`,
        `సూర్యాస్తమయానికి ముందు ప్రారంభించి, సూర్యుడు కనిపిస్తుండగానే అర్ఘ్యం ఇవ్వండి. పడమర ముఖంగా ఉండండి.`,
        `சூரிய அஸ்தமனத்துக்கு முன் தொடங்கி, சூரியன் தெரியும்போதே அர்க்கியம் விடவும். மேற்கு நோக்கி அமரவும்.`,
        `सूर्यास्त से पहले आरम्भ करें और सूर्य दिखते हुए ही अर्घ्य दें। पश्चिमाभिमुख रहें।`)
    },
    m: [ { opt:true, d:`अपवित्रः पवित्रो वा सर्वावस्थां गतोऽपि वा ।
यः स्मरेत्पुण्डरीकाक्षं स बाह्याभ्यन्तरः शुचिः ॥` } ],
    mean: L(`Pure or impure, in whatever state one may be, whoever remembers the lotus-eyed Lord becomes pure within and without.`,
      `ಶುದ್ಧನಾಗಿರಲಿ ಅಶುದ್ಧನಾಗಿರಲಿ, ಯಾವ ಸ್ಥಿತಿಯಲ್ಲಿದ್ದರೂ, ಪುಂಡರೀಕಾಕ್ಷನನ್ನು ಸ್ಮರಿಸುವವನು ಒಳಗೂ ಹೊರಗೂ ಶುದ್ಧನಾಗುತ್ತಾನೆ.`,
      `పవిత్రుడైనా అపవిత్రుడైనా, ఏ స్థితిలో ఉన్నా, పుండరీకాక్షుని స్మరించినవాడు లోపలా బయటా శుచి అవుతాడు.`,
      `தூய்மையானவனோ தூய்மையற்றவனோ, எந்த நிலையில் இருந்தாலும், புண்டரீகாக்ஷனை நினைப்பவன் உள்ளும் புறமும் தூய்மை அடைகிறான்.`,
      `पवित्र हो या अपवित्र, किसी भी अवस्था में हो, जो पुण्डरीकाक्ष भगवान् का स्मरण करता है वह भीतर-बाहर से शुद्ध हो जाता है।`) },

  { id:'acamana', t:`आचमनम्`, ash:'mental',
    how: L(`Hold the right palm cupped (gokarṇa mudrā), pour in a little water and sip it from the base of the thumb with each of the three names. Wash the hand. Then touch the face and body with the twelve names: Keśava, Nārāyaṇa, the right and left cheek with the thumb; Mādhava, Govinda, the right and left eye with the ring finger; Viṣṇu, Madhusūdana, the right and left nostril with the index finger; Trivikrama, Vāmana, the right and left ear with the little finger; Śrīdhara, Hṛṣīkeśa, the right and left shoulder with the middle finger; Padmanābha, the navel; Dāmodara, the top of the head, with all fingers.`,
      `ಬಲ ಅಂಗೈಯನ್ನು ಗೋಕರ್ಣ ಮುದ್ರೆಯಲ್ಲಿ ಹಿಡಿದು ಸ್ವಲ್ಪ ನೀರು ಹಾಕಿಕೊಂಡು, ಮೂರು ನಾಮಗಳಲ್ಲಿ ಪ್ರತಿಯೊಂದಕ್ಕೂ ಹೆಬ್ಬೆರಳಿನ ಬುಡದಿಂದ ಆಚಮನ ಮಾಡಿ. ಕೈ ತೊಳೆಯಿರಿ. ನಂತರ ಹನ್ನೆರಡು ನಾಮಗಳಿಂದ ಅಂಗಸ್ಪರ್ಶ: ಕೇಶವ, ನಾರಾಯಣ, ಹೆಬ್ಬೆರಳಿನಿಂದ ಬಲ ಮತ್ತು ಎಡ ಕೆನ್ನೆ; ಮಾಧವ, ಗೋವಿಂದ, ಉಂಗುರ ಬೆರಳಿನಿಂದ ಬಲ ಮತ್ತು ಎಡ ಕಣ್ಣು; ವಿಷ್ಣು, ಮಧುಸೂದನ, ತೋರು ಬೆರಳಿನಿಂದ ಬಲ ಮತ್ತು ಎಡ ಮೂಗಿನ ಹೊಳ್ಳೆ; ತ್ರಿವಿಕ್ರಮ, ವಾಮನ, ಕಿರು ಬೆರಳಿನಿಂದ ಬಲ ಮತ್ತು ಎಡ ಕಿವಿ; ಶ್ರೀಧರ, ಹೃಷೀಕೇಶ, ಮಧ್ಯದ ಬೆರಳಿನಿಂದ ಬಲ ಮತ್ತು ಎಡ ಭುಜ; ಪದ್ಮನಾಭ, ಹೊಕ್ಕುಳು; ದಾಮೋದರ, ಎಲ್ಲ ಬೆರಳುಗಳಿಂದ ನೆತ್ತಿ.`,
      `కుడి అరచేతిని గోకర్ణ ముద్రలో ఉంచి కొద్దిగా నీరు పోసుకొని, మూడు నామాలలో ఒక్కొక్కదానికి బొటనవేలి మొదలు నుండి ఆచమనం చేయండి. చేయి కడగండి. తర్వాత పన్నెండు నామాలతో అంగస్పర్శ: కేశవ, నారాయణ, బొటనవేలితో కుడి, ఎడమ చెంప; మాధవ, గోవింద, ఉంగరం వేలితో కుడి, ఎడమ కన్ను; విష్ణు, మధుసూదన, చూపుడు వేలితో కుడి, ఎడమ ముక్కు రంధ్రం; త్రివిక్రమ, వామన, చిటికెన వేలితో కుడి, ఎడమ చెవి; శ్రీధర, హృషీకేశ, మధ్య వేలితో కుడి, ఎడమ భుజం; పద్మనాభ, నాభి; దామోదర, అన్ని వేళ్ళతో తల.`,
      `வலது உள்ளங்கையைக் கோகர்ண முத்திரையில் வைத்துச் சிறிது நீர் விட்டு, மூன்று நாமங்களுக்கும் ஒவ்வொன்றாகக் கட்டைவிரல் அடியிலிருந்து ஆசமனம் செய்யவும். கையைக் கழுவவும். பிறகு பன்னிரண்டு நாமங்களால் அங்கஸ்பர்சம்: கேசவ, நாராயண, கட்டைவிரலால் வலது, இடது கன்னம்; மாதவ, கோவிந்த, மோதிர விரலால் வலது, இடது கண்; விஷ்ணு, மதுசூதன, ஆள்காட்டி விரலால் வலது, இடது நாசி; த்ரிவிக்ரம, வாமன, சுண்டு விரலால் வலது, இடது காது; ஸ்ரீதர, ஹ்ருஷீகேச, நடு விரலால் வலது, இடது தோள்; பத்மநாப, தொப்புள்; தாமோதர, எல்லா விரல்களாலும் உச்சந்தலை.`,
      `दाहिनी हथेली को गोकर्ण मुद्रा में रखकर थोड़ा जल लें और तीनों नामों में से प्रत्येक के साथ अंगूठे के मूल से आचमन करें। हाथ धो लें। फिर बारह नामों से अङ्गस्पर्श: केशव, नारायण, अंगूठे से दायाँ और बायाँ गाल; माधव, गोविन्द, अनामिका से दाईं और बाईं आँख; विष्णु, मधुसूदन, तर्जनी से दायाँ और बायाँ नथुना; त्रिविक्रम, वामन, कनिष्ठिका से दायाँ और बायाँ कान; श्रीधर, हृषीकेश, मध्यमा से दायाँ और बायाँ कंधा; पद्मनाभ, नाभि; दामोदर, सब उँगलियों से सिर।`),
    m: [ { d: M_ACAMANA },
         { d:`ॐ केशवाय नमः । ॐ नारायणाय नमः । ॐ माधवाय नमः । ॐ गोविन्दाय नमः ।
ॐ विष्णवे नमः । ॐ मधुसूदनाय नमः । ॐ त्रिविक्रमाय नमः । ॐ वामनाय नमः ।
ॐ श्रीधराय नमः । ॐ हृषीकेशाय नमः । ॐ पद्मनाभाय नमः । ॐ दामोदराय नमः ॥` } ],
    mean: L(`Salutations to Acyuta (the imperishable), Ananta (the endless) and Govinda. The twelve names of Viṣṇu sanctify the senses and the body.`,
      `ಅಚ್ಯುತ (ನಾಶವಿಲ್ಲದವನು), ಅನಂತ (ಕೊನೆಯಿಲ್ಲದವನು), ಗೋವಿಂದನಿಗೆ ನಮಸ್ಕಾರ. ವಿಷ್ಣುವಿನ ಹನ್ನೆರಡು ನಾಮಗಳು ಇಂದ್ರಿಯಗಳನ್ನೂ ದೇಹವನ್ನೂ ಪವಿತ್ರಗೊಳಿಸುತ್ತವೆ.`,
      `అచ్యుతునికి (నాశం లేనివాడు), అనంతునికి (అంతం లేనివాడు), గోవిందునికి నమస్కారం. విష్ణువు యొక్క పన్నెండు నామాలు ఇంద్రియాలను, దేహాన్ని పవిత్రం చేస్తాయి.`,
      `அச்யுதன் (அழிவற்றவன்), அனந்தன் (முடிவற்றவன்), கோவிந்தனுக்கு நமஸ்காரம். விஷ்ணுவின் பன்னிரண்டு நாமங்கள் புலன்களையும் உடலையும் தூய்மைப்படுத்துகின்றன.`,
      `अच्युत (अविनाशी), अनन्त (अन्तहीन) और गोविन्द को नमस्कार। विष्णु के बारह नाम इन्द्रियों और शरीर को पवित्र करते हैं।`) },

  { id:'ganapati', t:`विघ्नेश्वरध्यानम्`, ash:'mental',
    how: L(`With the fists lightly closed, tap the temples gently and meditate on Gaṇapati to remove obstacles.`,
      `ಮುಷ್ಟಿಗಳಿಂದ ಹಣೆಯ ಎರಡೂ ಬದಿಗಳನ್ನು ಮೆಲ್ಲನೆ ತಟ್ಟುತ್ತಾ ವಿಘ್ನ ನಿವಾರಣೆಗಾಗಿ ಗಣಪತಿಯನ್ನು ಧ್ಯಾನಿಸಿ.`,
      `పిడికిళ్ళతో కణతలపై మెల్లగా తట్టుతూ విఘ్న నివారణ కోసం గణపతిని ధ్యానించండి.`,
      `முஷ்டிகளால் நெற்றிப் பொட்டுகளில் மெதுவாகக் குட்டிக்கொண்டு, இடையூறுகள் நீங்க விநாயகரைத் தியானிக்கவும்.`,
      `मुट्ठियों से कनपटियों पर हल्के से थपथपाते हुए विघ्न निवारण के लिए गणपति का ध्यान करें।`),
    m: [ { d:`शुक्लाम्बरधरं विष्णुं शशिवर्णं चतुर्भुजम् ।
प्रसन्नवदनं ध्यायेत् सर्वविघ्नोपशान्तये ॥` } ],
    mean: L(`I meditate on the one clad in white, all-pervading, moon-hued, four-armed, with a gracious face, so that all obstacles are removed.`,
      `ಬಿಳಿ ವಸ್ತ್ರಧಾರಿ, ಸರ್ವವ್ಯಾಪಿ, ಚಂದ್ರನ ಬಣ್ಣದ, ನಾಲ್ಕು ಭುಜಗಳ, ಪ್ರಸನ್ನ ಮುಖದವನನ್ನು ಎಲ್ಲ ವಿಘ್ನಗಳ ಶಾಂತಿಗಾಗಿ ಧ್ಯಾನಿಸುತ್ತೇನೆ.`,
      `తెల్లని వస్త్రం ధరించినవాడు, సర్వవ్యాపి, చంద్రుని వర్ణం గలవాడు, నాలుగు భుజాలవాడు, ప్రసన్న ముఖుడైనవానిని సర్వ విఘ్నాల శాంతి కోసం ధ్యానిస్తాను.`,
      `வெண்ணிற ஆடை அணிந்தவர், எங்கும் நிறைந்தவர், சந்திர நிறத்தவர், நான்கு கரங்களுடையவர், மலர்ந்த முகத்தவரை எல்லா இடையூறுகளும் நீங்கத் தியானிக்கிறேன்.`,
      `श्वेत वस्त्रधारी, सर्वव्यापी, चन्द्रवर्ण, चतुर्भुज, प्रसन्नमुख देव का सब विघ्नों की शान्ति के लिए ध्यान करता हूँ।`) },

  { id:'pranayama', t:`प्राणायामः`, ash:'breath',
    how: L(`Close the right nostril with the right thumb and breathe in through the left. Close both nostrils with the thumb and the ring and little fingers, hold the breath and recite the mantra in the mind. Breathe out through the right nostril and touch the right ear. Many do this three times.`,
      `ಬಲ ಹೆಬ್ಬೆರಳಿನಿಂದ ಬಲ ಮೂಗಿನ ಹೊಳ್ಳೆ ಮುಚ್ಚಿ ಎಡದಿಂದ ಉಸಿರು ಎಳೆಯಿರಿ. ಹೆಬ್ಬೆರಳು, ಉಂಗುರ ಮತ್ತು ಕಿರು ಬೆರಳುಗಳಿಂದ ಎರಡೂ ಹೊಳ್ಳೆಗಳನ್ನು ಮುಚ್ಚಿ, ಉಸಿರು ಹಿಡಿದು ಮಂತ್ರವನ್ನು ಮನಸ್ಸಿನಲ್ಲಿ ಹೇಳಿ. ಬಲ ಹೊಳ್ಳೆಯಿಂದ ಉಸಿರು ಬಿಟ್ಟು ಬಲ ಕಿವಿಯನ್ನು ಸ್ಪರ್ಶಿಸಿ. ಹಲವರು ಇದನ್ನು ಮೂರು ಬಾರಿ ಮಾಡುತ್ತಾರೆ.`,
      `కుడి బొటనవేలితో కుడి ముక్కు రంధ్రం మూసి ఎడమ దాని ద్వారా శ్వాస పీల్చండి. బొటనవేలు, ఉంగరం, చిటికెన వేళ్ళతో రెండు రంధ్రాలూ మూసి, శ్వాస నిలిపి మంత్రాన్ని మనసులో చెప్పండి. కుడి రంధ్రం ద్వారా శ్వాస వదిలి కుడి చెవిని తాకండి. చాలామంది ఇది మూడుసార్లు చేస్తారు.`,
      `வலது கட்டைவிரலால் வலது நாசியை மூடி இடது நாசியால் மூச்சை இழுக்கவும். கட்டைவிரல், மோதிர விரல், சுண்டு விரலால் இரு நாசிகளையும் மூடி, மூச்சை அடக்கி மந்திரத்தை மனதிற்குள் சொல்லவும். வலது நாசியால் மூச்சை விட்டு வலது காதைத் தொடவும். பலர் இதை மூன்று முறை செய்வர்.`,
      `दाहिने अंगूठे से दायाँ नथुना बंद करके बाएँ से श्वास लें। अंगूठे, अनामिका और कनिष्ठिका से दोनों नथुने बंद करके श्वास रोकें और मन्त्र मन में बोलें। दाएँ नथुने से श्वास छोड़ें और दाहिना कान छुएँ। बहुत लोग यह तीन बार करते हैं।`),
    m: [ { d: M_PRANAYAMA } ],
    mean: L(`Om is joined to each of the seven worlds (bhūḥ to satyam), then comes the Gāyatrī, then its head: Om, the waters, the light, the essence, the nectar, Brahman, the three worlds, Om.`,
      `ಏಳು ಲೋಕಗಳಲ್ಲಿ (ಭೂಃ ಇಂದ ಸತ್ಯಂ) ಪ್ರತಿಯೊಂದಕ್ಕೂ ಓಂಕಾರ, ನಂತರ ಗಾಯತ್ರೀ, ನಂತರ ಅದರ ಶಿರಸ್ಸು: ಓಂ, ಜಲ, ಜ್ಯೋತಿ, ರಸ, ಅಮೃತ, ಬ್ರಹ್ಮ, ಮೂರು ಲೋಕಗಳು, ಓಂ.`,
      `ఏడు లోకాలలో (భూః నుండి సత్యం వరకు) ప్రతిదానికీ ఓంకారం, తర్వాత గాయత్రి, తర్వాత దాని శిరస్సు: ఓం, జలం, జ్యోతి, రసం, అమృతం, బ్రహ్మం, మూడు లోకాలు, ఓం.`,
      `ஏழு உலகங்கள் (பூ: முதல் ஸத்யம் வரை) ஒவ்வொன்றுக்கும் ஓங்காரம், பிறகு காயத்ரி, பிறகு அதன் சிரஸ்: ஓம், நீர், ஒளி, ரசம், அமிர்தம், பிரம்மம், மூவுலகம், ஓம்.`,
      `सात लोकों (भूः से सत्यम्) में से प्रत्येक के साथ ओङ्कार, फिर गायत्री, फिर उसका शिरस्: ॐ, जल, ज्योति, रस, अमृत, ब्रह्म, तीनों लोक, ॐ।`) },

  { id:'sankalpa', t:`सङ्कल्पः`, ash:'mental', sankalpa:true,
    how: L(`Place the left palm on the right thigh and the right palm over it, and state the resolve. You may say the short form, or the full form with today's Panchānga.`,
      `ಬಲ ತೊಡೆಯ ಮೇಲೆ ಎಡ ಅಂಗೈ, ಅದರ ಮೇಲೆ ಬಲ ಅಂಗೈ ಇಟ್ಟು ಸಂಕಲ್ಪ ಮಾಡಿ. ಸಂಕ್ಷಿಪ್ತ ರೂಪ ಅಥವಾ ಇಂದಿನ ಪಂಚಾಂಗದ ಪೂರ್ಣ ರೂಪವನ್ನು ಹೇಳಬಹುದು.`,
      `కుడి తొడపై ఎడమ అరచేయి, దానిపై కుడి అరచేయి ఉంచి సంకల్పం చెప్పండి. సంక్షిప్త రూపం లేదా నేటి పంచాంగంతో పూర్తి రూపం చెప్పవచ్చు.`,
      `வலது தொடையின் மேல் இடது உள்ளங்கை, அதன் மேல் வலது உள்ளங்கை வைத்து சங்கல்பம் செய்யவும். சுருக்க வடிவமோ இன்றைய பஞ்சாங்கத்துடன் முழு வடிவமோ சொல்லலாம்.`,
      `दाहिनी जाँघ पर बाईं हथेली और उस पर दाहिनी हथेली रखकर सङ्कल्प करें। संक्षिप्त रूप या आज के पञ्चाङ्ग सहित पूर्ण रूप बोल सकते हैं।`),
    m: [ { k:['pratah'], d: SK + `प्रातस्सन्ध्यामुपासिष्ये ॥` },
         { k:['madhya'], d: SK + `माध्याह्निकं करिष्ये ॥` },
         { k:['sayam'],  d: SK + `सायंसन्ध्यामुपासिष्ये ॥` } ],
    mean: L(`To remove all the sins I have gathered, and to please the Supreme Lord, I shall perform this Sandhyā worship.`,
      `ನಾನು ಗಳಿಸಿದ ಎಲ್ಲ ಪಾಪಗಳ ಕ್ಷಯಕ್ಕಾಗಿ, ಪರಮೇಶ್ವರನ ಪ್ರೀತಿಗಾಗಿ ಈ ಸಂಧ್ಯೋಪಾಸನೆಯನ್ನು ಮಾಡುತ್ತೇನೆ.`,
      `నేను సంపాదించిన సమస్త పాపాల క్షయం కోసం, పరమేశ్వరుని ప్రీతి కోసం ఈ సంధ్యోపాసన చేస్తాను.`,
      `நான் சேர்த்த எல்லாப் பாவங்களும் நீங்கவும், பரமேஸ்வரன் மகிழவும் இந்தச் சந்தியா உபாசனையைச் செய்கிறேன்.`,
      `अपने अर्जित सब पापों के क्षय के लिए और परमेश्वर की प्रीति के लिए मैं यह सन्ध्योपासना करता हूँ।`) },

  { id:'marjana', t:`मार्जनम्`, ash:'mental',
    how: L(`Dip the ring finger (or a blade of darbha) in water and sprinkle it on the head with each of the first seven lines, on the feet with the eighth, and on the head again with the ninth. With "Om bhūr bhuvas suvaḥ", move water around the head.`,
      `ಉಂಗುರ ಬೆರಳನ್ನು (ಅಥವಾ ದರ್ಭೆಯನ್ನು) ನೀರಿನಲ್ಲಿ ಅದ್ದಿ ಮೊದಲ ಏಳು ಸಾಲುಗಳಿಗೆ ತಲೆಯ ಮೇಲೆ, ಎಂಟನೆಯದಕ್ಕೆ ಪಾದಗಳ ಮೇಲೆ, ಒಂಬತ್ತನೆಯದಕ್ಕೆ ಮತ್ತೆ ತಲೆಯ ಮೇಲೆ ಪ್ರೋಕ್ಷಿಸಿ. "ಓಂ ಭೂರ್ಭುವಸ್ಸುವಃ" ಎಂದು ತಲೆಯ ಸುತ್ತ ನೀರನ್ನು ಸುತ್ತಿಸಿ.`,
      `ఉంగరం వేలిని (లేదా దర్భను) నీటిలో ముంచి మొదటి ఏడు పంక్తులకు తలపై, ఎనిమిదవదానికి పాదాలపై, తొమ్మిదవదానికి మళ్ళీ తలపై ప్రోక్షించండి. "ఓం భూర్భువస్సువః" అని తల చుట్టూ నీటిని తిప్పండి.`,
      `மோதிர விரலை (அல்லது தர்ப்பையை) நீரில் நனைத்து, முதல் ஏழு வரிகளுக்குத் தலையிலும், எட்டாவதற்குப் பாதங்களிலும், ஒன்பதாவதற்கு மீண்டும் தலையிலும் புரோக்ஷிக்கவும். "ஓம் பூர்புவஸ்ஸுவ:" என்று தலையைச் சுற்றி நீரைச் சுற்றவும்.`,
      `अनामिका (या दर्भ) को जल में डुबोकर पहली सात पंक्तियों पर सिर पर, आठवीं पर पैरों पर और नौवीं पर फिर सिर पर जल छिड़कें। "ॐ भूर्भुवस्सुवः" कहकर सिर के चारों ओर जल घुमाएँ।`),
    m: [ { d:`आपो हिष्ठेति मन्त्रस्य सिन्धुद्वीप ऋषिः । देवी गायत्री छन्दः । आपो देवता । अपां प्रोक्षणे विनियोगः ॥` },
         { d: M_APOHISHTA } ],
    mean: L(`O waters, you are the source of happiness. Give us strength, so that we may behold the great and the beautiful. Share with us your most auspicious essence, as loving mothers do. May we come to you fully, for the dwelling to which you lead us. O waters, give us birth anew.`,
      `ಓ ಜಲದೇವತೆಗಳೇ, ನೀವು ಸುಖದ ಮೂಲ. ನಮಗೆ ಶಕ್ತಿ ನೀಡಿ, ಮಹತ್ತಾದ ಸುಂದರವಾದುದನ್ನು ಕಾಣುವಂತೆ ಮಾಡಿ. ಪ್ರೀತಿಯ ತಾಯಂದಿರಂತೆ ನಿಮ್ಮ ಅತಿ ಮಂಗಳಕರ ರಸವನ್ನು ನಮಗೆ ಹಂಚಿ. ನೀವು ಕರೆದೊಯ್ಯುವ ನೆಲೆಗಾಗಿ ನಾವು ನಿಮ್ಮನ್ನು ಪೂರ್ಣವಾಗಿ ಸೇರೋಣ. ಓ ಜಲಗಳೇ, ನಮಗೆ ಹೊಸ ಜನ್ಮ ನೀಡಿ.`,
      `ఓ జలదేవతలారా, మీరు సుఖానికి మూలం. మాకు బలం ఇవ్వండి, మహత్తరమైన సుందరమైనదాన్ని చూడగలిగేలా చేయండి. ప్రేమగల తల్లుల వలె మీ అత్యంత మంగళకరమైన రసాన్ని మాకు పంచండి. మీరు నడిపించే నివాసం కోసం మేము మిమ్మల్ని పూర్తిగా చేరుదుము. ఓ జలాల్లారా, మాకు నూతన జన్మనివ్వండి.`,
      `நீர்த் தேவதைகளே, நீங்கள் இன்பத்தின் ஊற்று. எங்களுக்கு வலிமை தந்து, மகத்தானதும் அழகானதுமானதைக் காணச் செய்யுங்கள். அன்புள்ள தாய்களைப் போல உங்கள் மிக மங்களமான ரசத்தை எங்களுக்குப் பகிர்ந்தளியுங்கள். நீங்கள் அழைத்துச் செல்லும் இருப்பிடத்துக்காக நாங்கள் உங்களை முழுமையாக அடைவோமாக. நீர்களே, எங்களுக்குப் புதுப் பிறவி தாருங்கள்.`,
      `हे जल देवताओ, तुम सुख के स्रोत हो। हमें बल दो, जिससे हम महान् और सुन्दर का दर्शन करें। स्नेहमयी माताओं की भाँति अपना परम कल्याणकारी रस हमें दो। जिस धाम की ओर तुम ले जाते हो, उसके लिए हम तुम्हें पूर्णतः प्राप्त हों। हे जल, हमें नया जन्म दो।`) },

  { id:'prasana', t:`मन्त्राचमनम्`, ash:'mental',
    how: L(`Take a little water in the right palm, recite the mantra and drink it. Then do ācamana (step 2) again.`,
      `ಬಲ ಅಂಗೈಯಲ್ಲಿ ಸ್ವಲ್ಪ ನೀರು ತೆಗೆದುಕೊಂಡು ಮಂತ್ರ ಹೇಳಿ ಕುಡಿಯಿರಿ. ನಂತರ ಮತ್ತೆ ಆಚಮನ (ಹಂತ 2) ಮಾಡಿ.`,
      `కుడి అరచేతిలో కొద్దిగా నీరు తీసుకొని మంత్రం చెప్పి త్రాగండి. తర్వాత మళ్ళీ ఆచమనం (దశ 2) చేయండి.`,
      `வலது உள்ளங்கையில் சிறிது நீர் எடுத்து மந்திரம் சொல்லிப் பருகவும். பிறகு மீண்டும் ஆசமனம் (படி 2) செய்யவும்.`,
      `दाहिनी हथेली में थोड़ा जल लेकर मन्त्र बोलें और पी लें। फिर पुनः आचमन (चरण 2) करें।`),
    m: [ { k:['pratah'], d:`सूर्यश्च मा मन्युश्च मन्युपतयश्च मन्युकृतेभ्यः । पापेभ्यो रक्षन्ताम् ।
यद्रात्र्या पापमकार्षम् । मनसा वाचा हस्ताभ्याम् । पद्भ्यामुदरेण शिश्ना ।
रात्रिस्तदवलुम्पतु । यत्किञ्च दुरितं मयि । इदमहं माममृतयोनौ ।
सूर्ये ज्योतिषि जुहोमि स्वाहा ॥` },
         { k:['madhya'], d:`आपः पुनन्तु पृथिवीं पृथिवी पूता पुनातु माम् ।
पुनन्तु ब्रह्मणस्पतिर्ब्रह्म पूता पुनातु माम् ।
यदुच्छिष्टमभोज्यं यद्वा दुश्चरितं मम ।
सर्वं पुनन्तु मामापोऽसतां च प्रतिग्रहग्ं स्वाहा ॥` },
         { k:['sayam'], d:`अग्निश्च मा मन्युश्च मन्युपतयश्च मन्युकृतेभ्यः । पापेभ्यो रक्षन्ताम् ।
यदह्ना पापमकार्षम् । मनसा वाचा हस्ताभ्याम् । पद्भ्यामुदरेण शिश्ना ।
अहस्तदवलुम्पतु । यत्किञ्च दुरितं मयि । इदमहं माममृतयोनौ ।
सत्ये ज्योतिषि जुहोमि स्वाहा ॥` } ],
    meanK: {
      pratah: L(`May the Sun, anger and the lords of anger protect me from sins born of anger. Whatever sin I committed in the night, by mind, speech, hands, feet, stomach or organ, may the night wipe it away. Whatever evil is in me, I offer it, and myself, into the Sun, the light that is the source of immortality.`,
        `ಸೂರ್ಯ, ಕೋಪ, ಕೋಪದ ಅಧಿಪತಿಗಳು ಕೋಪದಿಂದಾದ ಪಾಪಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸಲಿ. ರಾತ್ರಿಯಲ್ಲಿ ಮನಸ್ಸು, ಮಾತು, ಕೈಗಳು, ಕಾಲುಗಳು, ಹೊಟ್ಟೆ, ಜನನೇಂದ್ರಿಯಗಳಿಂದ ಮಾಡಿದ ಪಾಪವನ್ನು ರಾತ್ರಿ ಅಳಿಸಲಿ. ನನ್ನಲ್ಲಿರುವ ಯಾವುದೇ ದುರಿತವನ್ನು, ನನ್ನನ್ನೂ ಸೇರಿಸಿ, ಅಮೃತದ ಮೂಲವಾದ ಸೂರ್ಯಜ್ಯೋತಿಯಲ್ಲಿ ಅರ್ಪಿಸುತ್ತೇನೆ.`,
        `సూర్యుడు, కోపం, కోపానికి అధిపతులు కోపం వల్ల కలిగిన పాపాల నుండి నన్ను రక్షించుగాక. రాత్రి మనసు, వాక్కు, చేతులు, కాళ్ళు, ఉదరం, జననేంద్రియాలతో చేసిన పాపాన్ని రాత్రి తుడిచివేయుగాక. నాలోని ఏ దురితాన్నైనా, నన్ను కూడా, అమృతానికి మూలమైన సూర్యజ్యోతిలో అర్పిస్తున్నాను.`,
        `சூரியனும், கோபமும், கோபத்தின் அதிபதிகளும் கோபத்தால் வந்த பாவங்களிலிருந்து என்னைக் காக்கட்டும். இரவில் மனம், சொல், கைகள், கால்கள், வயிறு, ஜனனேந்திரியம் ஆகியவற்றால் செய்த பாவத்தை இரவே அழிக்கட்டும். என்னிடம் உள்ள எந்தத் தீமையையும், என்னையும், அமிர்தத்தின் மூலமான சூரிய ஜோதியில் அர்ப்பணிக்கிறேன்.`,
        `सूर्य, मन्यु (क्रोध) और मन्यु के अधिपति क्रोध से हुए पापों से मेरी रक्षा करें। रात्रि में मन, वाणी, हाथों, पैरों, उदर और उपस्थ से जो पाप किया, उसे रात्रि मिटा दे। मुझमें जो भी दुरित है, उसे और स्वयं को अमृत के स्रोत सूर्य-ज्योति में अर्पित करता हूँ।`),
      madhya: L(`May the waters purify the earth; may the purified earth purify me. May Brahmaṇaspati and the purified Veda purify me. Whatever is left over or unfit to eat, whatever wrong I have done, and gifts accepted from the unworthy: may the waters purify me of all of it.`,
        `ಜಲಗಳು ಭೂಮಿಯನ್ನು ಶುದ್ಧಗೊಳಿಸಲಿ; ಶುದ್ಧವಾದ ಭೂಮಿ ನನ್ನನ್ನು ಶುದ್ಧಗೊಳಿಸಲಿ. ಬ್ರಹ್ಮಣಸ್ಪತಿ ಮತ್ತು ಪವಿತ್ರ ವೇದ ನನ್ನನ್ನು ಶುದ್ಧಗೊಳಿಸಲಿ. ಉಚ್ಛಿಷ್ಟ, ತಿನ್ನಬಾರದ್ದು, ನಾನು ಮಾಡಿದ ದುಶ್ಚರಿತ, ಅಯೋಗ್ಯರಿಂದ ಪಡೆದ ದಾನ: ಎಲ್ಲದರಿಂದಲೂ ಜಲಗಳು ನನ್ನನ್ನು ಶುದ್ಧಗೊಳಿಸಲಿ.`,
        `జలాలు భూమిని పవిత్రం చేయుగాక; పవిత్రమైన భూమి నన్ను పవిత్రం చేయుగాక. బ్రహ్మణస్పతి, పవిత్రమైన వేదం నన్ను పవిత్రం చేయుగాక. ఉచ్ఛిష్టం, తినకూడనిది, నేను చేసిన దుశ్చరితం, అయోగ్యుల నుండి పొందిన దానం: అన్నిటి నుండీ జలాలు నన్ను పవిత్రం చేయుగాక.`,
        `நீர் பூமியைத் தூய்மைப்படுத்தட்டும்; தூய்மையான பூமி என்னைத் தூய்மைப்படுத்தட்டும். பிரம்மணஸ்பதியும் தூய வேதமும் என்னைத் தூய்மைப்படுத்தட்டும். எச்சில், உண்ணத் தகாதது, நான் செய்த தீய செயல், தகாதவரிடம் பெற்ற தானம்: எல்லாவற்றிலிருந்தும் நீர் என்னைத் தூய்மைப்படுத்தட்டும்.`,
        `जल पृथ्वी को पवित्र करें; पवित्र पृथ्वी मुझे पवित्र करे। ब्रह्मणस्पति और पवित्र वेद मुझे पवित्र करें। उच्छिष्ट, अभोज्य, मेरा दुश्चरित और अयोग्य से लिया दान: इन सबसे जल मुझे पवित्र करें।`),
      sayam: L(`May Agni, anger and the lords of anger protect me from sins born of anger. Whatever sin I committed in the day, by mind, speech, hands, feet, stomach or organ, may the day wipe it away. Whatever evil is in me, I offer it, and myself, into Truth, the light that is the source of immortality.`,
        `ಅಗ್ನಿ, ಕೋಪ, ಕೋಪದ ಅಧಿಪತಿಗಳು ಕೋಪದಿಂದಾದ ಪಾಪಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸಲಿ. ಹಗಲಿನಲ್ಲಿ ಮನಸ್ಸು, ಮಾತು, ಕೈಗಳು, ಕಾಲುಗಳು, ಹೊಟ್ಟೆ, ಜನನೇಂದ್ರಿಯಗಳಿಂದ ಮಾಡಿದ ಪಾಪವನ್ನು ಹಗಲು ಅಳಿಸಲಿ. ನನ್ನಲ್ಲಿರುವ ಯಾವುದೇ ದುರಿತವನ್ನು, ನನ್ನನ್ನೂ ಸೇರಿಸಿ, ಅಮೃತದ ಮೂಲವಾದ ಸತ್ಯಜ್ಯೋತಿಯಲ್ಲಿ ಅರ್ಪಿಸುತ್ತೇನೆ.`,
        `అగ్ని, కోపం, కోపానికి అధిపతులు కోపం వల్ల కలిగిన పాపాల నుండి నన్ను రక్షించుగాక. పగలు మనసు, వాక్కు, చేతులు, కాళ్ళు, ఉదరం, జననేంద్రియాలతో చేసిన పాపాన్ని పగలు తుడిచివేయుగాక. నాలోని ఏ దురితాన్నైనా, నన్ను కూడా, అమృతానికి మూలమైన సత్యజ్యోతిలో అర్పిస్తున్నాను.`,
        `அக்னியும், கோபமும், கோபத்தின் அதிபதிகளும் கோபத்தால் வந்த பாவங்களிலிருந்து என்னைக் காக்கட்டும். பகலில் மனம், சொல், கைகள், கால்கள், வயிறு, ஜனனேந்திரியம் ஆகியவற்றால் செய்த பாவத்தைப் பகலே அழிக்கட்டும். என்னிடம் உள்ள எந்தத் தீமையையும், என்னையும், அமிர்தத்தின் மூலமான ஸத்ய ஜோதியில் அர்ப்பணிக்கிறேன்.`,
        `अग्नि, मन्यु और मन्यु के अधिपति क्रोध से हुए पापों से मेरी रक्षा करें। दिन में मन, वाणी, हाथों, पैरों, उदर और उपस्थ से जो पाप किया, उसे दिन मिटा दे। मुझमें जो भी दुरित है, उसे और स्वयं को अमृत के स्रोत सत्य-ज्योति में अर्पित करता हूँ।`) } },

  { id:'punarmarjana', t:`पुनर्मार्जनम्`, ash:'mental',
    how: L(`Do ācamana. Sprinkle water on the head as in Mārjana while reciting "dadhikrāvṇṇo" and then "āpo hi ṣṭhā" again.`,
      `ಆಚಮನ ಮಾಡಿ. "ದಧಿಕ್ರಾವ್ಣ್ಣೋ" ಮತ್ತು ಮತ್ತೆ "ಆಪೋ ಹಿ ಷ್ಠಾ" ಹೇಳುತ್ತಾ ಮಾರ್ಜನದಂತೆ ತಲೆಯ ಮೇಲೆ ನೀರು ಪ್ರೋಕ್ಷಿಸಿ.`,
      `ఆచమనం చేయండి. "దధిక్రావ్ణ్ణో", తర్వాత మళ్ళీ "ఆపో హి ష్ఠా" చెబుతూ మార్జనంలా తలపై నీరు ప్రోక్షించండి.`,
      `ஆசமனம் செய்யவும். "ததிக்ராவ்ண்ணோ", பிறகு மீண்டும் "ஆபோ ஹி ஷ்டா" சொல்லி மார்ஜனம் போலத் தலையில் நீர் புரோக்ஷிக்கவும்.`,
      `आचमन करें। "दधिक्राव्ण्णो" और फिर "आपो हि ष्ठा" कहते हुए मार्जन की भाँति सिर पर जल छिड़कें।`),
    m: [ { d:`दधिक्राव्ण्णो अकारिषं जिष्णोरश्वस्य वाजिनः ।
सुरभि नो मुखा करत्प्रण आयूग्ंषि तारिषत् ॥` },
         { d: M_APOHISHTA },
         { opt:true, d:`हिरण्यवर्णाः शुचयः पावकाः यासु जातः कश्यपो यास्विन्द्रः ।
अग्निं या गर्भं दधिरे विरूपास्ता न आपः शग्ं स्योना भवन्तु ॥
यासाग्ं राजा वरुणो याति मध्ये सत्यानृते अवपश्यं जनानाम् ।
मधुश्चुतः शुचयो याः पावकास्ता न आपः शग्ं स्योना भवन्तु ॥
यासां देवा दिवि कृण्वन्ति भक्षं या अन्तरिक्षे बहुधा भवन्ति ।
याः पृथिवीं पयसोन्दन्ति शुक्रास्ता न आपः शग्ं स्योना भवन्तु ॥
शिवेन मा चक्षुषा पश्यतापः शिवया तनुवोप स्पृशत त्वचं मे ।
सर्वाग्ं अग्नीग्ं रप्सुषदो हुवे वो मयि वर्चो बलमोजो नि धत्त ॥` } ],
    mean: L(`I praise Dadhikrāvan, the swift, victorious horse (the Sun). May he make our mouths fragrant and lengthen our lives. Some families add the Hiraṇyavarṇāḥ hymn: may the golden, pure waters, in which Kaśyapa and Indra were born and which hold Agni in their womb, be gentle and kind to us.`,
      `ವೇಗವಾದ, ವಿಜಯಿಯಾದ ಅಶ್ವ ದಧಿಕ್ರಾವನನ್ನು (ಸೂರ್ಯನನ್ನು) ಸ್ತುತಿಸುತ್ತೇನೆ. ಅವನು ನಮ್ಮ ಮುಖಗಳನ್ನು ಸುಗಂಧಮಯಗೊಳಿಸಿ ಆಯುಸ್ಸನ್ನು ಹೆಚ್ಚಿಸಲಿ. ಕೆಲವು ಮನೆತನಗಳು "ಹಿರಣ್ಯವರ್ಣಾಃ" ಸೂಕ್ತವನ್ನೂ ಸೇರಿಸುತ್ತಾರೆ: ಕಶ್ಯಪ, ಇಂದ್ರರು ಜನಿಸಿದ, ಅಗ್ನಿಯನ್ನು ಗರ್ಭದಲ್ಲಿ ಧರಿಸಿದ ಸುವರ್ಣವರ್ಣದ ಪವಿತ್ರ ಜಲಗಳು ನಮಗೆ ಮಂಗಳಕರವಾಗಲಿ.`,
      `వేగవంతుడు, విజయుడు అయిన అశ్వం దధిక్రావుని (సూర్యుని) స్తుతిస్తున్నాను. అతడు మా ముఖాలను సుగంధభరితం చేసి ఆయుష్షును పెంచుగాక. కొన్ని కుటుంబాలు "హిరణ్యవర్ణాః" సూక్తాన్ని కూడా చేరుస్తాయి: కశ్యపుడు, ఇంద్రుడు జన్మించిన, అగ్నిని గర్భంలో ధరించిన బంగారు వన్నె గల పవిత్ర జలాలు మాకు శుభకరమగుగాక.`,
      `விரைவான, வெற்றியுடைய குதிரையான ததிக்ராவனை (சூரியனை) துதிக்கிறேன். அவன் எங்கள் வாயை நறுமணமாக்கி ஆயுளை நீட்டட்டும். சில குடும்பங்கள் "ஹிரண்யவர்ணா:" சூக்தத்தையும் சேர்ப்பர்: கச்யபரும் இந்திரனும் பிறந்த, அக்னியைக் கருவில் தாங்கிய பொன்னிறத் தூய நீர் எங்களுக்கு மங்களமாகட்டும்.`,
      `तेज़, विजयी अश्व दधिक्रावा (सूर्य) की स्तुति करता हूँ। वह हमारे मुख सुगन्धित करे और आयु बढ़ाए। कुछ परिवार "हिरण्यवर्णाः" सूक्त भी जोड़ते हैं: जिनमें कश्यप और इन्द्र उत्पन्न हुए, जो अग्नि को गर्भ में धारण करते हैं, वे स्वर्णवर्ण पवित्र जल हमारे लिए कल्याणकारी हों।`) },

  { id:'aghamarshana', t:`अघमर्षणम्`, ash:'mental', opt:true,
    how: L(`Hold water in the right palm near the nose, recite the mantra, breathe out onto the water as if expelling sin, and throw it to your left without looking at it. Do ācamana.`,
      `ಬಲ ಅಂಗೈಯಲ್ಲಿ ನೀರನ್ನು ಮೂಗಿನ ಬಳಿ ಹಿಡಿದು ಮಂತ್ರ ಹೇಳಿ, ಪಾಪವನ್ನು ಹೊರಹಾಕುವಂತೆ ಅದರ ಮೇಲೆ ಉಸಿರು ಬಿಟ್ಟು, ನೋಡದೆ ಎಡಕ್ಕೆ ಎಸೆಯಿರಿ. ಆಚಮನ ಮಾಡಿ.`,
      `కుడి అరచేతిలో నీటిని ముక్కు దగ్గర పట్టుకొని మంత్రం చెప్పి, పాపాన్ని బయటకు తోసినట్లు దానిపై శ్వాస వదిలి, చూడకుండా ఎడమవైపు విసరండి. ఆచమనం చేయండి.`,
      `வலது உள்ளங்கையில் நீரை மூக்கருகே பிடித்து மந்திரம் சொல்லி, பாவத்தை வெளியேற்றுவது போல் அதன் மேல் மூச்சை விட்டு, பார்க்காமல் இடப்புறம் எறியவும். ஆசமனம் செய்யவும்.`,
      `दाहिनी हथेली में जल नाक के पास रखकर मन्त्र बोलें, पाप को बाहर निकालने के भाव से उस पर श्वास छोड़ें, और बिना देखे बाईं ओर फेंक दें। आचमन करें।`),
    m: [ { d:`द्रुपदादिव मुमुचानः स्विन्नः स्नात्वी मलादिव ।
पूतं पवित्रेणेवाज्यमापः शुन्धन्तु मैनसः ॥` } ],
    mean: L(`As one freed from a wooden post, as one cleansed of dirt by bathing after sweating, as ghee purified through a strainer, may the waters cleanse me of sin.`,
      `ಮರದ ಕಂಬದಿಂದ ಬಿಡುಗಡೆಯಾದವನಂತೆ, ಬೆವರಿದ ನಂತರ ಸ್ನಾನದಿಂದ ಮಲ ತೊಳೆದವನಂತೆ, ಜರಡಿಯಿಂದ ಶುದ್ಧವಾದ ತುಪ್ಪದಂತೆ, ಜಲಗಳು ನನ್ನನ್ನು ಪಾಪದಿಂದ ಶುದ್ಧಗೊಳಿಸಲಿ.`,
      `చెక్క స్తంభం నుండి విడుదలైనవాని వలె, చెమట పట్టిన తర్వాత స్నానంతో మలినం కడిగినవాని వలె, వడపోతతో శుద్ధమైన నెయ్యి వలె, జలాలు నన్ను పాపం నుండి శుద్ధి చేయుగాక.`,
      `மரக் கம்பத்திலிருந்து விடுபட்டவன் போல, வியர்த்தபின் நீராடி அழுக்கு நீங்கியவன் போல, வடிகட்டியால் தூய்மையான நெய் போல, நீர் என்னைப் பாவத்திலிருந்து தூய்மைப்படுத்தட்டும்.`,
      `जैसे काठ के खूँटे से छूटा हुआ, जैसे पसीने के बाद स्नान से मैल धोया हुआ, जैसे छलनी से शुद्ध किया घी, वैसे जल मुझे पाप से शुद्ध करें।`) },

  { id:'arghya', t:`अर्घ्यप्रदानम्`, ash:'do',
    how: L(`Do prāṇāyāma and say the saṅkalpa for arghya. Fill both palms with water and, reciting the Gāyatrī each time, pour it out from the fingertips towards the Sun.`,
      `ಪ್ರಾಣಾಯಾಮ ಮಾಡಿ ಅರ್ಘ್ಯದ ಸಂಕಲ್ಪ ಹೇಳಿ. ಎರಡೂ ಅಂಗೈಗಳಲ್ಲಿ ನೀರು ತುಂಬಿ, ಪ್ರತಿ ಬಾರಿ ಗಾಯತ್ರಿಯನ್ನು ಹೇಳುತ್ತಾ ಬೆರಳ ತುದಿಗಳಿಂದ ಸೂರ್ಯನ ಕಡೆಗೆ ಬಿಡಿ.`,
      `ప్రాణాయామం చేసి అర్ఘ్య సంకల్పం చెప్పండి. రెండు అరచేతులలో నీరు నింపి, ప్రతిసారీ గాయత్రి చెబుతూ వేళ్ళ కొనల నుండి సూర్యుని వైపు విడువండి.`,
      `பிராணாயாமம் செய்து அர்க்கிய சங்கல்பம் சொல்லவும். இரு உள்ளங்கைகளிலும் நீர் நிரப்பி, ஒவ்வொரு முறையும் காயத்ரி சொல்லி விரல் நுனிகள் வழியாகச் சூரியனை நோக்கி விடவும்.`,
      `प्राणायाम करके अर्घ्य का सङ्कल्प करें। दोनों हथेलियों में जल भरकर, हर बार गायत्री बोलते हुए उँगलियों के अग्रभाग से सूर्य की ओर छोड़ें।`),
    howK: {
      pratah: L(`Offer 3 arghyas standing, facing east, with the heels slightly raised, before sunrise.`,
        `ಸೂರ್ಯೋದಯಕ್ಕೆ ಮುನ್ನ ಪೂರ್ವಾಭಿಮುಖವಾಗಿ ನಿಂತು, ಹಿಮ್ಮಡಿ ಸ್ವಲ್ಪ ಎತ್ತಿ 3 ಅರ್ಘ್ಯ ಕೊಡಿ.`,
        `సూర్యోదయానికి ముందు తూర్పు ముఖంగా నిలబడి, మడమలు కొద్దిగా ఎత్తి 3 అర్ఘ్యాలు ఇవ్వండి.`,
        `சூரிய உதயத்துக்கு முன் கிழக்கு நோக்கி நின்று, குதிகாலைச் சற்று உயர்த்தி 3 அர்க்கியம் விடவும்.`,
        `सूर्योदय से पहले पूर्वाभिमुख खड़े होकर, एड़ियाँ थोड़ी उठाकर 3 अर्घ्य दें।`),
      madhya: L(`Offer 2 arghyas standing, facing the Sun.`,
        `ಸೂರ್ಯನ ಕಡೆಗೆ ನಿಂತು 2 ಅರ್ಘ್ಯ ಕೊಡಿ.`,
        `సూర్యుని వైపు నిలబడి 2 అర్ఘ్యాలు ఇవ్వండి.`,
        `சூரியனை நோக்கி நின்று 2 அர்க்கியம் விடவும்.`,
        `सूर्य की ओर खड़े होकर 2 अर्घ्य दें।`),
      sayam: L(`Offer 3 arghyas facing west, before sunset. Many sit for the evening arghya.`,
        `ಸೂರ್ಯಾಸ್ತಕ್ಕೆ ಮುನ್ನ ಪಶ್ಚಿಮಾಭಿಮುಖವಾಗಿ 3 ಅರ್ಘ್ಯ ಕೊಡಿ. ಸಂಜೆ ಹಲವರು ಕುಳಿತು ಕೊಡುತ್ತಾರೆ.`,
        `సూర్యాస్తమయానికి ముందు పడమర ముఖంగా 3 అర్ఘ్యాలు ఇవ్వండి. సాయంత్రం చాలామంది కూర్చొని ఇస్తారు.`,
        `அஸ்தமனத்துக்கு முன் மேற்கு நோக்கி 3 அர்க்கியம் விடவும். மாலையில் பலர் அமர்ந்து விடுவர்.`,
        `सूर्यास्त से पहले पश्चिमाभिमुख 3 अर्घ्य दें। सायंकाल बहुत लोग बैठकर देते हैं।`)
    },
    m: [ { k:['pratah'], d: SK + `प्रातस्सन्ध्यार्घ्यप्रदानं करिष्ये ॥` },
         { k:['madhya'], d: SK + `माध्याह्निकार्घ्यप्रदानं करिष्ये ॥` },
         { k:['sayam'],  d: SK + `सायंसन्ध्यार्घ्यप्रदानं करिष्ये ॥` },
         { d: M_GAYATRI } ],
    mean: MEAN_GAYATRI },

  { id:'turiya', t:`प्रायश्चित्तार्घ्यम्`, ash:'do', late:true,
    how: L(`If the proper time has passed (after sunrise in the morning, after the noon window, after sunset in the evening), do prāṇāyāma, say this saṅkalpa and offer one more arghya with the mantra below.`,
      `ಸರಿಯಾದ ಕಾಲ ಮೀರಿದ್ದರೆ (ಬೆಳಿಗ್ಗೆ ಸೂರ್ಯೋದಯದ ನಂತರ, ಮಧ್ಯಾಹ್ನದ ಕಾಲದ ನಂತರ, ಸಂಜೆ ಸೂರ್ಯಾಸ್ತದ ನಂತರ), ಪ್ರಾಣಾಯಾಮ ಮಾಡಿ ಈ ಸಂಕಲ್ಪ ಹೇಳಿ ಕೆಳಗಿನ ಮಂತ್ರದೊಂದಿಗೆ ಇನ್ನೊಂದು ಅರ್ಘ್ಯ ಕೊಡಿ.`,
      `సరైన కాలం దాటితే (ఉదయం సూర్యోదయం తర్వాత, మధ్యాహ్న కాలం తర్వాత, సాయంత్రం సూర్యాస్తమయం తర్వాత), ప్రాణాయామం చేసి ఈ సంకల్పం చెప్పి క్రింది మంత్రంతో మరొక అర్ఘ్యం ఇవ్వండి.`,
      `உரிய நேரம் கடந்துவிட்டால் (காலையில் சூரிய உதயத்துக்குப் பின், மத்தியான நேரத்துக்குப் பின், மாலையில் அஸ்தமனத்துக்குப் பின்), பிராணாயாமம் செய்து இந்தச் சங்கல்பம் சொல்லிக் கீழே உள்ள மந்திரத்துடன் இன்னொரு அர்க்கியம் விடவும்.`,
      `यदि उचित समय निकल गया हो (प्रातः सूर्योदय के बाद, मध्याह्न काल के बाद, सायं सूर्यास्त के बाद), तो प्राणायाम करके यह सङ्कल्प बोलें और नीचे के मन्त्र से एक और अर्घ्य दें।`),
    m: [ { d: SK + `कालातीत प्रायश्चित्तार्थं तुरीयार्घ्यप्रदानं करिष्ये ॥` },
         { d:`ॐ भूः । ॐ भुवः । ओग्ं सुवः । ॐ महः । ॐ जनः । ॐ तपः । ओग्ं सत्यम् ।
ॐ तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि । धियो यो नः प्रचोदयात् ।
ॐ भूः । ॐ भुवः । ओग्ं सुवः । ॐ महः । ॐ जनः । ॐ तपः । ओग्ं सत्यम् ॥` } ],
    mean: L(`An extra arghya in expiation for missing the proper time, offered with the Gāyatrī enclosed on both sides by the seven vyāhṛtis.`,
      `ಕಾಲ ಮೀರಿದ್ದಕ್ಕೆ ಪ್ರಾಯಶ್ಚಿತ್ತವಾಗಿ, ಎರಡೂ ಕಡೆ ಏಳು ವ್ಯಾಹೃತಿಗಳಿಂದ ಆವೃತವಾದ ಗಾಯತ್ರಿಯೊಂದಿಗೆ ಕೊಡುವ ಹೆಚ್ಚುವರಿ ಅರ್ಘ್ಯ.`,
      `కాలం దాటినందుకు ప్రాయశ్చిత్తంగా, రెండు వైపులా ఏడు వ్యాహృతులతో ఆవరించిన గాయత్రితో ఇచ్చే అదనపు అర్ఘ్యం.`,
      `நேரம் கடந்ததற்குப் பிராயச்சித்தமாக, இருபுறமும் ஏழு வியாஹ்ருதிகளால் சூழப்பட்ட காயத்ரியுடன் விடும் கூடுதல் அர்க்கியம்.`,
      `समय बीत जाने के प्रायश्चित्त हेतु, दोनों ओर सात व्याहृतियों से सम्पुटित गायत्री के साथ दिया जाने वाला अतिरिक्त अर्घ्य।`) },

  { id:'brahma', t:`असावादित्यो ब्रह्म`, ash:'mental',
    how: L(`Take a little water in the right palm, turn once around yourself clockwise (or circle the water around you) with "Om bhūr bhuvas suvaḥ", and sprinkle it. Then sit, do ācamana and contemplate with folded hands.`,
      `ಬಲ ಅಂಗೈಯಲ್ಲಿ ಸ್ವಲ್ಪ ನೀರು ತೆಗೆದುಕೊಂಡು "ಓಂ ಭೂರ್ಭುವಸ್ಸುವಃ" ಎಂದು ನಿಮ್ಮ ಸುತ್ತ ಒಮ್ಮೆ ಪ್ರದಕ್ಷಿಣೆ ಮಾಡಿ (ಅಥವಾ ನೀರನ್ನು ಸುತ್ತಿಸಿ) ಪ್ರೋಕ್ಷಿಸಿ. ನಂತರ ಕುಳಿತು ಆಚಮನ ಮಾಡಿ, ಕೈ ಮುಗಿದು ಧ್ಯಾನಿಸಿ.`,
      `కుడి అరచేతిలో కొద్దిగా నీరు తీసుకొని "ఓం భూర్భువస్సువః" అని మీ చుట్టూ ఒకసారి ప్రదక్షిణ చేసి (లేదా నీటిని చుట్టూ తిప్పి) ప్రోక్షించండి. తర్వాత కూర్చొని ఆచమనం చేసి, చేతులు జోడించి ధ్యానించండి.`,
      `வலது உள்ளங்கையில் சிறிது நீர் எடுத்து "ஓம் பூர்புவஸ்ஸுவ:" என்று உங்களைச் சுற்றி ஒருமுறை பிரதக்ஷிணம் செய்து (அல்லது நீரைச் சுற்றி) புரோக்ஷிக்கவும். பிறகு அமர்ந்து ஆசமனம் செய்து, கைகூப்பித் தியானிக்கவும்.`,
      `दाहिनी हथेली में थोड़ा जल लेकर "ॐ भूर्भुवस्सुवः" कहते हुए अपने चारों ओर एक बार प्रदक्षिणा करें (या जल घुमाएँ) और छिड़कें। फिर बैठकर आचमन करें और हाथ जोड़कर ध्यान करें।`),
    m: [ { d:`ॐ भूर्भुवस्सुवः ॥
असावादित्यो ब्रह्म । ब्रह्मैवाहमस्मि ॥` } ],
    mean: L(`That Sun is Brahman. I am Brahman itself.`, `ಆ ಸೂರ್ಯನೇ ಬ್ರಹ್ಮ. ನಾನೇ ಆ ಬ್ರಹ್ಮ.`, `ఆ సూర్యుడే బ్రహ్మం. నేనే ఆ బ్రహ్మాన్ని.`, `அந்தச் சூரியனே பிரம்மம். நானே அந்தப் பிரம்மம்.`, `वह सूर्य ही ब्रह्म है। मैं ही वह ब्रह्म हूँ।`) },

  { id:'tarpana', t:`तर्पणम्`, ash:'skip',
    how: L(`Do ācamana. For each name, pour a little water from the fingertips (deva-tīrtha) into a plate.`,
      `ಆಚಮನ ಮಾಡಿ. ಪ್ರತಿ ನಾಮಕ್ಕೂ ಬೆರಳ ತುದಿಗಳಿಂದ (ದೇವತೀರ್ಥ) ತಟ್ಟೆಗೆ ಸ್ವಲ್ಪ ನೀರು ಬಿಡಿ.`,
      `ఆచమనం చేయండి. ప్రతి నామానికీ వేళ్ళ కొనల నుండి (దేవతీర్థం) పళ్ళెంలోకి కొద్దిగా నీరు విడువండి.`,
      `ஆசமனம் செய்யவும். ஒவ்வொரு நாமத்துக்கும் விரல் நுனிகள் வழியாக (தேவதீர்த்தம்) தட்டில் சிறிது நீர் விடவும்.`,
      `आचमन करें। प्रत्येक नाम के साथ उँगलियों के अग्रभाग (देवतीर्थ) से थाली में थोड़ा जल छोड़ें।`),
    m: [ { k:['pratah'], d:`सन्ध्यां तर्पयामि । गायत्रीं तर्पयामि । ब्राह्मीं तर्पयामि । निमृजीं तर्पयामि ॥` },
         { k:['madhya'], d:`सन्ध्यां तर्पयामि । सावित्रीं तर्पयामि । रौद्रीं तर्पयामि । निमृजीं तर्पयामि ॥` },
         { k:['sayam'],  d:`सन्ध्यां तर्पयामि । सरस्वतीं तर्पयामि । वैष्णवीं तर्पयामि । निमृजीं तर्पयामि ॥` },
         { tamil:true, d:`आदित्यं तर्पयामि । सोमं तर्पयामि । अङ्गारकं तर्पयामि । बुधं तर्पयामि ।
बृहस्पतिं तर्पयामि । शुक्रं तर्पयामि । शनैश्चरं तर्पयामि । राहुं तर्पयामि । केतुं तर्पयामि ॥
केशवं तर्पयामि । नारायणं तर्पयामि । माधवं तर्पयामि । गोविन्दं तर्पयामि ।
विष्णुं तर्पयामि । मधुसूदनं तर्पयामि । त्रिविक्रमं तर्पयामि । वामनं तर्पयामि ।
श्रीधरं तर्पयामि । हृषीकेशं तर्पयामि । पद्मनाभं तर्पयामि । दामोदरं तर्पयामि ॥` } ],
    mean: L(`I satisfy Sandhyā and the goddess of this time of day: Gāyatrī (Brāhmī) at dawn, Sāvitrī (Raudrī) at noon, Sarasvatī (Vaiṣṇavī) at dusk, and Nimṛjī, the purifier. Tamil Smārta families instead offer tarpaṇa to the nine planets and the twelve names of Viṣṇu.`,
      `ಸಂಧ್ಯೆಯನ್ನೂ ಈ ಕಾಲದ ದೇವಿಯನ್ನೂ ತೃಪ್ತಿಪಡಿಸುತ್ತೇನೆ: ಬೆಳಿಗ್ಗೆ ಗಾಯತ್ರೀ (ಬ್ರಾಹ್ಮೀ), ಮಧ್ಯಾಹ್ನ ಸಾವಿತ್ರೀ (ರೌದ್ರೀ), ಸಂಜೆ ಸರಸ್ವತೀ (ವೈಷ್ಣವೀ), ಮತ್ತು ಶುದ್ಧೀಕರಿಸುವ ನಿಮೃಜೀ. ತಮಿಳು ಸ್ಮಾರ್ತ ಮನೆತನಗಳು ಇದರ ಬದಲು ನವಗ್ರಹಗಳಿಗೂ ವಿಷ್ಣುವಿನ ಹನ್ನೆರಡು ನಾಮಗಳಿಗೂ ತರ್ಪಣ ಕೊಡುತ್ತಾರೆ.`,
      `సంధ్యను, ఈ కాలపు దేవిని తృప్తిపరుస్తున్నాను: ఉదయం గాయత్రి (బ్రాహ్మీ), మధ్యాహ్నం సావిత్రి (రౌద్రీ), సాయంత్రం సరస్వతి (వైష్ణవీ), మరియు శుద్ధి చేసే నిమృజీ. తమిళ స్మార్త కుటుంబాలు దీనికి బదులుగా నవగ్రహాలకు, విష్ణువు యొక్క పన్నెండు నామాలకు తర్పణం ఇస్తారు.`,
      `சந்தியையும் இந்நேரத்தின் தேவியையும் திருப்திப்படுத்துகிறேன்: காலையில் காயத்ரி (பிராம்மீ), நண்பகலில் ஸாவித்ரி (ரௌத்ரீ), மாலையில் ஸரஸ்வதி (வைஷ்ணவீ), தூய்மைப்படுத்தும் நிம்ருஜீ. தமிழ் ஸ்மார்த்தக் குடும்பங்கள் இதற்குப் பதிலாக நவக்கிரகங்களுக்கும் விஷ்ணுவின் பன்னிரண்டு நாமங்களுக்கும் தர்ப்பணம் செய்வர்.`,
      `सन्ध्या और इस काल की देवी को तृप्त करता हूँ: प्रातः गायत्री (ब्राह्मी), मध्याह्न सावित्री (रौद्री), सायं सरस्वती (वैष्णवी), और शुद्ध करने वाली निमृजी। तमिल स्मार्त परिवार इसके स्थान पर नवग्रहों और विष्णु के बारह नामों को तर्पण देते हैं।`) },

  { id:'asana', t:`आसनम्`, ash:'skip',
    how: L(`The Gāyatrī japa begins here. Do ācamana, sprinkle water on your seat and touch it with the mantra below.`,
      `ಇಲ್ಲಿಂದ ಗಾಯತ್ರೀ ಜಪ ಆರಂಭ. ಆಚಮನ ಮಾಡಿ, ಆಸನದ ಮೇಲೆ ನೀರು ಪ್ರೋಕ್ಷಿಸಿ ಕೆಳಗಿನ ಮಂತ್ರದೊಂದಿಗೆ ಸ್ಪರ್ಶಿಸಿ.`,
      `ఇక్కడి నుండి గాయత్రీ జపం ప్రారంభం. ఆచమనం చేసి, ఆసనంపై నీరు ప్రోక్షించి క్రింది మంత్రంతో తాకండి.`,
      `இங்கிருந்து காயத்ரி ஜபம் தொடங்குகிறது. ஆசமனம் செய்து, ஆசனத்தில் நீர் தெளித்துக் கீழே உள்ள மந்திரத்துடன் தொடவும்.`,
      `यहाँ से गायत्री जप आरम्भ होता है। आचमन करके आसन पर जल छिड़कें और नीचे के मन्त्र से उसे स्पर्श करें।`),
    m: [ { d:`पृथिवीति मन्त्रस्य मेरुपृष्ठ ऋषिः । सुतलं छन्दः । कूर्मो देवता । आसने विनियोगः ॥
पृथ्वि त्वया धृता लोका देवि त्वं विष्णुना धृता ।
त्वं च धारय मां देवि पवित्रं कुरु चासनम् ॥` } ],
    mean: L(`O Earth, the worlds are held by you, and you are held by Viṣṇu. O Goddess, hold me up and make this seat pure.`,
      `ಓ ಭೂದೇವಿ, ಲೋಕಗಳನ್ನು ನೀನು ಧರಿಸಿರುವೆ, ನಿನ್ನನ್ನು ವಿಷ್ಣು ಧರಿಸಿರುವನು. ದೇವಿ, ನನ್ನನ್ನು ಧರಿಸು, ಈ ಆಸನವನ್ನು ಪವಿತ್ರಗೊಳಿಸು.`,
      `ఓ భూదేవీ, లోకాలను నీవు ధరించావు, నిన్ను విష్ణువు ధరించాడు. దేవీ, నన్ను ధరించు, ఈ ఆసనాన్ని పవిత్రం చేయి.`,
      `பூமாதேவியே, உலகங்கள் உன்னால் தாங்கப்படுகின்றன, நீ விஷ்ணுவால் தாங்கப்படுகிறாய். தேவியே, என்னைத் தாங்கி, இந்த ஆசனத்தைப் புனிதமாக்கு.`,
      `हे पृथ्वी, लोक तुमसे धारित हैं और तुम विष्णु से धारित हो। हे देवी, मुझे धारण करो और इस आसन को पवित्र करो।`) },

  { id:'japapranayama', t:`जपाङ्ग प्राणायामः`, ash:'skip',
    how: L(`State the ṛṣi, chandas and devatā of the praṇava, the seven vyāhṛtis, the Gāyatrī and its head, then do prāṇāyāma three times (step 4).`,
      `ಪ್ರಣವ, ಏಳು ವ್ಯಾಹೃತಿಗಳು, ಗಾಯತ್ರೀ ಮತ್ತು ಅದರ ಶಿರಸ್ಸಿನ ಋಷಿ, ಛಂದಸ್ಸು, ದೇವತೆಗಳನ್ನು ಹೇಳಿ, ನಂತರ ಮೂರು ಬಾರಿ ಪ್ರಾಣಾಯಾಮ (ಹಂತ 4) ಮಾಡಿ.`,
      `ప్రణవం, ఏడు వ్యాహృతులు, గాయత్రి మరియు దాని శిరస్సు యొక్క ఋషి, ఛందస్సు, దేవతలను చెప్పి, తర్వాత మూడుసార్లు ప్రాణాయామం (దశ 4) చేయండి.`,
      `பிரணவம், ஏழு வியாஹ்ருதிகள், காயத்ரி, அதன் சிரஸ் ஆகியவற்றின் ரிஷி, சந்தஸ், தேவதையைச் சொல்லி, பிறகு மூன்று முறை பிராணாயாமம் (படி 4) செய்யவும்.`,
      `प्रणव, सात व्याहृतियों, गायत्री और उसके शिरस् के ऋषि, छन्द और देवता कहें, फिर तीन बार प्राणायाम (चरण 4) करें।`),
    m: [ { d:`प्रणवस्य ऋषिर्ब्रह्मा । देवी गायत्री छन्दः । परमात्मा देवता ।
भूरादि सप्तव्याहृतीनाम् अत्रि भृगु कुत्स वसिष्ठ गौतम काश्यप आङ्गिरस ऋषयः ।
गायत्री उष्णिक् अनुष्टुप् बृहती पङ्क्तिः त्रिष्टुप् जगत्यः छन्दांसि ।
अग्नि वायु अर्क वागीश वरुण इन्द्र विश्वेदेवा देवताः ।
सावित्र्या ऋषिर्विश्वामित्रः । देवी गायत्री छन्दः । सविता देवता ।
गायत्रीशिरसो ब्रह्मा ऋषिः । अनुष्टुप् छन्दः । परमात्मा देवता ।
सर्वेषां प्राणायामे विनियोगः ॥` } ],
    mean: L(`Brahmā is the seer of Om. The seven vyāhṛtis were seen by Atri, Bhṛgu, Kutsa, Vasiṣṭha, Gautama, Kāśyapa and Āṅgirasa, in seven metres, with Agni, Vāyu, the Sun, Bṛhaspati, Varuṇa, Indra and the Viśvedevas as deities. Viśvāmitra is the seer of the Gāyatrī and Savitṛ its deity.`,
      `ಓಂಕಾರದ ಋಷಿ ಬ್ರಹ್ಮ. ಏಳು ವ್ಯಾಹೃತಿಗಳನ್ನು ಅತ್ರಿ, ಭೃಗು, ಕುತ್ಸ, ವಸಿಷ್ಠ, ಗೌತಮ, ಕಾಶ್ಯಪ, ಆಂಗಿರಸರು ಏಳು ಛಂದಸ್ಸುಗಳಲ್ಲಿ ಕಂಡರು; ಅಗ್ನಿ, ವಾಯು, ಸೂರ್ಯ, ಬೃಹಸ್ಪತಿ, ವರುಣ, ಇಂದ್ರ, ವಿಶ್ವೇದೇವರು ದೇವತೆಗಳು. ಗಾಯತ್ರಿಯ ಋಷಿ ವಿಶ್ವಾಮಿತ್ರ, ದೇವತೆ ಸವಿತೃ.`,
      `ఓంకారానికి ఋషి బ్రహ్మ. ఏడు వ్యాహృతులను అత్రి, భృగు, కుత్స, వసిష్ఠ, గౌతమ, కాశ్యప, ఆంగిరసులు ఏడు ఛందస్సులలో దర్శించారు; అగ్ని, వాయువు, సూర్యుడు, బృహస్పతి, వరుణుడు, ఇంద్రుడు, విశ్వేదేవులు దేవతలు. గాయత్రికి ఋషి విశ్వామిత్రుడు, దేవత సవిత.`,
      `ஓங்காரத்தின் ரிஷி பிரம்மா. ஏழு வியாஹ்ருதிகளை அத்ரி, ப்ருகு, குத்ஸர், வஸிஷ்டர், கௌதமர், காச்யபர், ஆங்கிரஸர் ஏழு சந்தஸ்களில் கண்டனர்; அக்னி, வாயு, சூரியன், ப்ருஹஸ்பதி, வருணன், இந்திரன், விஸ்வேதேவர் தேவதைகள். காயத்ரியின் ரிஷி விஸ்வாமித்திரர், தேவதை ஸவிதா.`,
      `ओङ्कार के ऋषि ब्रह्मा हैं। सात व्याहृतियों के द्रष्टा अत्रि, भृगु, कुत्स, वसिष्ठ, गौतम, काश्यप और आङ्गिरस हैं, सात छन्दों में, और अग्नि, वायु, सूर्य, बृहस्पति, वरुण, इन्द्र तथा विश्वेदेव देवता हैं। गायत्री के ऋषि विश्वामित्र और देवता सविता हैं।`) },

  { id:'japasankalpa', t:`जपसङ्कल्पः`, ash:'mental',
    how: L(`Say the saṅkalpa for japa, with the hands as in step 5.`,
      `ಹಂತ 5 ರಂತೆ ಕೈಗಳನ್ನಿಟ್ಟು ಜಪದ ಸಂಕಲ್ಪ ಹೇಳಿ.`,
      `దశ 5 లోలా చేతులు ఉంచి జప సంకల్పం చెప్పండి.`,
      `படி 5 போலக் கைகளை வைத்து ஜப சங்கல்பம் சொல்லவும்.`,
      `चरण 5 की भाँति हाथ रखकर जप का सङ्कल्प करें।`),
    m: [ { k:['pratah'], d: SK + `प्रातस्सन्ध्या गायत्री महामन्त्रजपं करिष्ये ॥` },
         { k:['madhya'], d: SK + `माध्याह्निक गायत्री महामन्त्रजपं करिष्ये ॥` },
         { k:['sayam'],  d: SK + `सायंसन्ध्या गायत्री महामन्त्रजपं करिष्ये ॥` } ],
    mean: L(`To please the Supreme Lord, I shall perform japa of the great Gāyatrī mantra.`,
      `ಪರಮೇಶ್ವರನ ಪ್ರೀತಿಗಾಗಿ ಗಾಯತ್ರೀ ಮಹಾಮಂತ್ರದ ಜಪವನ್ನು ಮಾಡುತ್ತೇನೆ.`,
      `పరమేశ్వరుని ప్రీతి కోసం గాయత్రీ మహామంత్ర జపం చేస్తాను.`,
      `பரமேஸ்வரன் மகிழ காயத்ரி மகாமந்திர ஜபம் செய்கிறேன்.`,
      `परमेश्वर की प्रीति के लिए गायत्री महामन्त्र का जप करता हूँ।`) },

  { id:'avahana', t:`गायत्र्यावाहनम्`, ash:'skip',
    how: L(`Invite the Goddess Gāyatrī with folded hands.`, `ಕೈ ಮುಗಿದು ಗಾಯತ್ರೀ ದೇವಿಯನ್ನು ಆವಾಹಿಸಿ.`, `చేతులు జోడించి గాయత్రీ దేవిని ఆవాహన చేయండి.`, `கைகூப்பிக் காயத்ரி தேவியை ஆவாஹனம் செய்யவும்.`, `हाथ जोड़कर गायत्री देवी का आवाहन करें।`),
    m: [ { d:`आयात्वित्यनुवाकस्य वामदेव ऋषिः । अनुष्टुप् छन्दः । गायत्री देवता । गायत्र्यावाहने विनियोगः ॥
आयातु वरदा देवी अक्षरं ब्रह्मसम्मितम् ।
गायत्रीं छन्दसां मातेदं ब्रह्म जुषस्व नः ॥
ओजोऽसि सहोऽसि बलमसि भ्राजोऽसि देवानां धामनामासि
विश्वमसि विश्वायुः सर्वमसि सर्वायुरभिभूरोम् ॥
गायत्रीमावाहयामि । सावित्रीमावाहयामि । सरस्वतीमावाहयामि ।
छन्दर्षीनावाहयामि । श्रियमावाहयामि ॥` } ],
    mean: L(`Come, boon-giving Goddess, imperishable, equal to the Veda. Gāyatrī, mother of the metres, accept this prayer. You are vigour, endurance, strength and radiance; you are the abode and name of the gods; you are all, the life of all, the all-conquering. I invoke Gāyatrī, Sāvitrī, Sarasvatī, the metres and seers, and Śrī.`,
      `ವರದಾಯಿನಿ ದೇವಿ, ಅಕ್ಷರಳೇ, ವೇದಸಮಾನಳೇ, ಬಾ. ಛಂದಸ್ಸುಗಳ ತಾಯಿ ಗಾಯತ್ರೀ, ಈ ಪ್ರಾರ್ಥನೆಯನ್ನು ಸ್ವೀಕರಿಸು. ನೀನು ಓಜಸ್ಸು, ಸಹಸ್ಸು, ಬಲ, ತೇಜಸ್ಸು; ದೇವತೆಗಳ ಧಾಮವೂ ನಾಮವೂ ನೀನು; ನೀನೇ ಎಲ್ಲವೂ, ಎಲ್ಲರ ಆಯುಸ್ಸು. ಗಾಯತ್ರೀ, ಸಾವಿತ್ರೀ, ಸರಸ್ವತೀ, ಛಂದಸ್ಸು ಋಷಿಗಳು ಮತ್ತು ಶ್ರೀಯನ್ನು ಆವಾಹಿಸುತ್ತೇನೆ.`,
      `వరాలిచ్చే దేవీ, అక్షరమైనదానా, వేదసమానురాలా, రమ్ము. ఛందస్సుల తల్లి గాయత్రీ, ఈ ప్రార్థనను స్వీకరించు. నీవు ఓజస్సు, సహస్సు, బలం, తేజస్సు; దేవతల ధామం, నామం నీవే; నీవే సర్వం, అందరి ఆయువు. గాయత్రిని, సావిత్రిని, సరస్వతిని, ఛందస్సులను ఋషులను, శ్రీని ఆవాహన చేస్తున్నాను.`,
      `வரமளிக்கும் தேவியே, அழிவற்றவளே, வேதத்துக்கு இணையானவளே, வருக. சந்தஸ்களின் தாயான காயத்ரியே, இந்தப் பிரார்த்தனையை ஏற்றுக்கொள். நீ ஓஜஸ், ஸஹஸ், பலம், தேஜஸ்; தேவர்களின் இருப்பிடமும் பெயரும் நீயே; நீயே எல்லாம், எல்லோரின் ஆயுள். காயத்ரி, ஸாவித்ரி, ஸரஸ்வதி, சந்தஸ்-ரிஷிகள், ஸ்ரீ ஆகியோரை ஆவாஹனம் செய்கிறேன்.`,
      `हे वरदायिनी देवी, अक्षर, वेदसम्मित, आओ। छन्दों की माता गायत्री, यह प्रार्थना स्वीकार करो। तुम ओज, सह, बल और तेज हो; देवों का धाम और नाम हो; तुम सब कुछ हो, सबकी आयु हो। मैं गायत्री, सावित्री, सरस्वती, छन्दों और ऋषियों तथा श्री का आवाहन करता हूँ।`) },

  { id:'nyasa', t:`करन्यास अङ्गन्यासौ`, ash:'skip', opt:true,
    how: L(`Touch the fingers (kara-nyāsa), then the heart, head, crown, shoulders and eyes, and finally snap the fingers around the head (aṅga-nyāsa), placing each part of the Gāyatrī.`,
      `ಬೆರಳುಗಳನ್ನು (ಕರನ್ಯಾಸ), ನಂತರ ಹೃದಯ, ತಲೆ, ಶಿಖೆ, ಭುಜಗಳು, ಕಣ್ಣುಗಳನ್ನು ಸ್ಪರ್ಶಿಸಿ, ಕೊನೆಗೆ ತಲೆಯ ಸುತ್ತ ಚಿಟಿಕೆ ಹೊಡೆಯಿರಿ (ಅಂಗನ್ಯಾಸ), ಗಾಯತ್ರಿಯ ಪ್ರತಿ ಭಾಗವನ್ನು ನ್ಯಾಸ ಮಾಡುತ್ತಾ.`,
      `వేళ్ళను (కరన్యాసం), తర్వాత హృదయం, తల, శిఖ, భుజాలు, కళ్ళను తాకి, చివరగా తల చుట్టూ చిటికె వేయండి (అంగన్యాసం), గాయత్రిలోని ప్రతి భాగాన్ని న్యాసం చేస్తూ.`,
      `விரல்களையும் (கரந்யாஸம்), பிறகு இதயம், தலை, சிகை, தோள்கள், கண்களையும் தொட்டு, இறுதியில் தலையைச் சுற்றிச் சொடுக்கவும் (அங்கந்யாஸம்), காயத்ரியின் ஒவ்வொரு பகுதியையும் நியாஸம் செய்தபடி.`,
      `उँगलियों (करन्यास), फिर हृदय, सिर, शिखा, कंधों और नेत्रों को स्पर्श करें, और अन्त में सिर के चारों ओर चुटकी बजाएँ (अङ्गन्यास), गायत्री के प्रत्येक भाग का न्यास करते हुए।`),
    m: [ { d:`ॐ तत्सवितुः ब्रह्मात्मने अङ्गुष्ठाभ्यां नमः । वरेण्यं विष्ण्वात्मने तर्जनीभ्यां नमः ।
भर्गो देवस्य रुद्रात्मने मध्यमाभ्यां नमः । धीमहि सत्यात्मने अनामिकाभ्यां नमः ।
धियो यो नः ज्ञानात्मने कनिष्ठिकाभ्यां नमः । प्रचोदयात् सर्वात्मने करतलकरपृष्ठाभ्यां नमः ॥` },
         { d:`ॐ तत्सवितुः ब्रह्मात्मने हृदयाय नमः । वरेण्यं विष्ण्वात्मने शिरसे स्वाहा ।
भर्गो देवस्य रुद्रात्मने शिखायै वषट् । धीमहि सत्यात्मने कवचाय हुम् ।
धियो यो नः ज्ञानात्मने नेत्रत्रयाय वौषट् । प्रचोदयात् सर्वात्मने अस्त्राय फट् ।
भूर्भुवस्सुवरोमिति दिग्बन्धः ॥` } ],
    mean: L(`Each part of the Gāyatrī is placed on the body as Brahmā, Viṣṇu, Rudra, Truth, Knowledge and the Self of all.`,
      `ಗಾಯತ್ರಿಯ ಪ್ರತಿ ಭಾಗವನ್ನು ಬ್ರಹ್ಮ, ವಿಷ್ಣು, ರುದ್ರ, ಸತ್ಯ, ಜ್ಞಾನ, ಸರ್ವಾತ್ಮ ರೂಪವಾಗಿ ದೇಹದಲ್ಲಿ ನ್ಯಾಸ ಮಾಡಲಾಗುತ್ತದೆ.`,
      `గాయత్రిలోని ప్రతి భాగాన్ని బ్రహ్మ, విష్ణు, రుద్ర, సత్య, జ్ఞాన, సర్వాత్మ రూపంగా దేహంలో న్యాసం చేస్తారు.`,
      `காயத்ரியின் ஒவ்வொரு பகுதியும் பிரம்மா, விஷ்ணு, ருத்ரன், ஸத்யம், ஞானம், ஸர்வாத்மா வடிவில் உடலில் நியாஸம் செய்யப்படுகிறது.`,
      `गायत्री के प्रत्येक भाग का ब्रह्मा, विष्णु, रुद्र, सत्य, ज्ञान और सर्वात्मा रूप में शरीर पर न्यास किया जाता है।`) },

  { id:'dhyana', t:`गायत्रीध्यानम्`, ash:'skip',
    how: L(`Meditate on the goddess of this time of day in the orb of the Sun.`, `ಸೂರ್ಯಮಂಡಲದಲ್ಲಿ ಈ ಕಾಲದ ದೇವಿಯನ್ನು ಧ್ಯಾನಿಸಿ.`, `సూర్యమండలంలో ఈ కాలపు దేవిని ధ్యానించండి.`, `சூரிய மண்டலத்தில் இந்நேரத்தின் தேவியைத் தியானிக்கவும்.`, `सूर्यमण्डल में इस काल की देवी का ध्यान करें।`),
    m: [ { k:['pratah'], d:`प्रातर्ध्यायामि गायत्रीं रविमण्डलमध्यगाम् ।
ऋग्वेदमुच्चारयन्तीं रक्तवर्णां कुमारिकाम् ।
अक्षमालाकरां ब्रह्मदैवत्यां हंसवाहनाम् ॥` },
         { k:['madhya'], d:`मध्यन्दिने तु सावित्रीं रविमण्डलमध्यगाम् ।
यजुर्वेदं व्याहरन्तीं श्वेतां शूलकरां शिवाम् ।
युवतीं रुद्रदैवत्यां ध्यायामि वृषवाहनाम् ॥` },
         { k:['sayam'], d:`सायं सरस्वतीं श्यामां रविमण्डलमध्यगाम् ।
सामवेदं व्याहरन्तीं चक्रायुधधरां शुभाम् ।
ध्यायामि विष्णुदैवत्यां वृद्धां गरुडवाहनाम् ॥` },
         { d:`मुक्ताविद्रुमहेमनीलधवलच्छायैर्मुखैस्त्रीक्षणै-
र्युक्तामिन्दुकलानिबद्धमकुटां तत्त्वार्थवर्णात्मिकाम् ।
गायत्रीं वरदाभयाङ्कुशकशाः शुभ्रं कपालं गुणं
शङ्खं चक्रमथारविन्दयुगलं हस्तैर्वहन्तीं भजे ॥` },
         { d:`यो देवः सविताऽस्माकं धियो धर्मादिगोचराः ।
प्रेरयेत्तस्य यद्भर्गस्तद्वरेण्यमुपास्महे ॥` } ],
    meanK: {
      pratah: L(`In the morning I meditate on Gāyatrī in the orb of the Sun: a red-hued maiden reciting the Ṛgveda, holding a rosary, with Brahmā as her deity, riding a swan. The second verse, the five-faced, ten-armed Gāyatrī, is the common dhyāna for all three times.`,
        `ಬೆಳಿಗ್ಗೆ ಸೂರ್ಯಮಂಡಲದ ಮಧ್ಯದಲ್ಲಿರುವ ಗಾಯತ್ರಿಯನ್ನು ಧ್ಯಾನಿಸುತ್ತೇನೆ: ಋಗ್ವೇದವನ್ನು ಉಚ್ಚರಿಸುವ ಕೆಂಪು ವರ್ಣದ ಕುಮಾರಿ, ಅಕ್ಷಮಾಲೆ ಹಿಡಿದವಳು, ಬ್ರಹ್ಮ ದೇವತೆ, ಹಂಸವಾಹನೆ. ಎರಡನೆಯ ಶ್ಲೋಕದ ಐದು ಮುಖ, ಹತ್ತು ಕೈಗಳ ಗಾಯತ್ರೀ ಧ್ಯಾನ ಮೂರೂ ಕಾಲಗಳಿಗೂ ಸಾಮಾನ್ಯ.`,
        `ఉదయం సూర్యమండల మధ్యంలో ఉన్న గాయత్రిని ధ్యానిస్తాను: ఋగ్వేదాన్ని ఉచ్చరించే ఎర్రని వన్నె గల కుమారి, అక్షమాల ధరించినది, బ్రహ్మ దేవతగా, హంసవాహన. రెండవ శ్లోకంలోని ఐదు ముఖాలు, పది చేతుల గాయత్రీ ధ్యానం మూడు కాలాలకూ సాధారణం.`,
        `காலையில் சூரிய மண்டலத்தின் நடுவில் உள்ள காயத்ரியைத் தியானிக்கிறேன்: ரிக்வேதம் ஓதும் சிவந்த நிறக் கன்னி, அக்ஷமாலை ஏந்தியவள், பிரம்மாவைத் தேவதையாகக் கொண்டவள், அன்ன வாகனத்தவள். இரண்டாவது சுலோகத்தின் ஐந்து முகம், பத்துக் கரங்கள் கொண்ட காயத்ரி தியானம் மூன்று வேளைக்கும் பொதுவானது.`,
        `प्रातः सूर्यमण्डल के मध्य स्थित गायत्री का ध्यान करता हूँ: ऋग्वेद का उच्चारण करती रक्तवर्णा कुमारी, अक्षमाला धारण किए, ब्रह्मा देवता, हंसवाहना। दूसरे श्लोक का पञ्चमुखी, दशभुजा गायत्री ध्यान तीनों कालों के लिए सामान्य है।`),
      madhya: L(`At noon, Sāvitrī in the orb of the Sun: a white young woman reciting the Yajurveda, holding a trident, with Rudra as her deity, riding a bull. The second verse, the five-faced, ten-armed Gāyatrī, is the common dhyāna for all three times.`,
        `ಮಧ್ಯಾಹ್ನ ಸೂರ್ಯಮಂಡಲದಲ್ಲಿ ಸಾವಿತ್ರಿ: ಯಜುರ್ವೇದವನ್ನು ಉಚ್ಚರಿಸುವ ಶ್ವೇತವರ್ಣದ ಯುವತಿ, ಶೂಲಧಾರಿಣಿ, ರುದ್ರ ದೇವತೆ, ವೃಷಭವಾಹನೆ. ಎರಡನೆಯ ಶ್ಲೋಕದ ಐದು ಮುಖ, ಹತ್ತು ಕೈಗಳ ಗಾಯತ್ರೀ ಧ್ಯಾನ ಮೂರೂ ಕಾಲಗಳಿಗೂ ಸಾಮಾನ್ಯ.`,
        `మధ్యాహ్నం సూర్యమండలంలో సావిత్రి: యజుర్వేదాన్ని ఉచ్చరించే తెల్లని యువతి, శూలధారిణి, రుద్ర దేవతగా, వృషభవాహన. రెండవ శ్లోకంలోని ఐదు ముఖాలు, పది చేతుల గాయత్రీ ధ్యానం మూడు కాలాలకూ సాధారణం.`,
        `நண்பகலில் சூரிய மண்டலத்தில் ஸாவித்ரி: யஜுர்வேதம் ஓதும் வெண்ணிற யுவதி, சூலம் ஏந்தியவள், ருத்ரனைத் தேவதையாகக் கொண்டவள், ரிஷப வாகனத்தவள். இரண்டாவது சுலோகத்தின் ஐந்து முகம், பத்துக் கரங்கள் கொண்ட காயத்ரி தியானம் மூன்று வேளைக்கும் பொதுவானது.`,
        `मध्याह्न में सूर्यमण्डल में सावित्री: यजुर्वेद का उच्चारण करती श्वेतवर्णा युवती, शूलधारिणी, रुद्र देवता, वृषभवाहना। दूसरे श्लोक का पञ्चमुखी, दशभुजा गायत्री ध्यान तीनों कालों के लिए सामान्य है।`),
      sayam: L(`At dusk, Sarasvatī in the orb of the Sun: dark-hued and aged, reciting the Sāmaveda, holding the discus, with Viṣṇu as her deity, riding Garuḍa. The second verse, the five-faced, ten-armed Gāyatrī, is the common dhyāna for all three times.`,
        `ಸಂಜೆ ಸೂರ್ಯಮಂಡಲದಲ್ಲಿ ಸರಸ್ವತಿ: ಸಾಮವೇದವನ್ನು ಉಚ್ಚರಿಸುವ ಶ್ಯಾಮವರ್ಣದ ವೃದ್ಧೆ, ಚಕ್ರಧಾರಿಣಿ, ವಿಷ್ಣು ದೇವತೆ, ಗರುಡವಾಹನೆ. ಎರಡನೆಯ ಶ್ಲೋಕದ ಐದು ಮುಖ, ಹತ್ತು ಕೈಗಳ ಗಾಯತ್ರೀ ಧ್ಯಾನ ಮೂರೂ ಕಾಲಗಳಿಗೂ ಸಾಮಾನ್ಯ.`,
        `సాయంత్రం సూర్యమండలంలో సరస్వతి: సామవేదాన్ని ఉచ్చరించే శ్యామవర్ణ వృద్ధ, చక్రధారిణి, విష్ణు దేవతగా, గరుడవాహన. రెండవ శ్లోకంలోని ఐదు ముఖాలు, పది చేతుల గాయత్రీ ధ్యానం మూడు కాలాలకూ సాధారణం.`,
        `மாலையில் சூரிய மண்டலத்தில் ஸரஸ்வதி: ஸாமவேதம் ஓதும் கருநிற முதியவள், சக்கரம் ஏந்தியவள், விஷ்ணுவைத் தேவதையாகக் கொண்டவள், கருட வாகனத்தவள். இரண்டாவது சுலோகத்தின் ஐந்து முகம், பத்துக் கரங்கள் கொண்ட காயத்ரி தியானம் மூன்று வேளைக்கும் பொதுவானது.`,
        `सायं सूर्यमण्डल में सरस्वती: सामवेद का उच्चारण करती श्यामवर्णा वृद्धा, चक्रधारिणी, विष्णु देवता, गरुड़वाहना। दूसरे श्लोक का पञ्चमुखी, दशभुजा गायत्री ध्यान तीनों कालों के लिए सामान्य है।`) } },

  { id:'japa', t:`गायत्रीजपः`, ash:'mental', counter:true,
    how: L(`Recite the Gāyatrī 108 times (best), 28 times, or at least 10 times, counting on the fingers or a mālā with the hand covered by a cloth. Pause at the end of each of the four lines. The counter below can keep count.`,
      `ಗಾಯತ್ರಿಯನ್ನು 108 ಬಾರಿ (ಉತ್ತಮ), 28 ಬಾರಿ, ಅಥವಾ ಕನಿಷ್ಠ 10 ಬಾರಿ, ಬೆರಳುಗಳಲ್ಲಿ ಅಥವಾ ಜಪಮಾಲೆಯಲ್ಲಿ ಎಣಿಸುತ್ತಾ, ಕೈಯನ್ನು ವಸ್ತ್ರದಿಂದ ಮುಚ್ಚಿ ಜಪಿಸಿ. ನಾಲ್ಕು ಸಾಲುಗಳ ಪ್ರತಿ ಕೊನೆಯಲ್ಲಿ ನಿಲ್ಲಿಸಿ. ಕೆಳಗಿನ ಎಣಿಕೆ ಎಣಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.`,
      `గాయత్రిని 108 సార్లు (ఉత్తమం), 28 సార్లు, లేదా కనీసం 10 సార్లు, వేళ్ళపై లేదా జపమాలతో లెక్కిస్తూ, చేతిని వస్త్రంతో కప్పి జపించండి. నాలుగు పంక్తులలో ప్రతి దాని చివర ఆగండి. క్రింది లెక్కింపు సహాయపడుతుంది.`,
      `காயத்ரியை 108 முறை (உத்தமம்), 28 முறை, அல்லது குறைந்தது 10 முறை, விரல்களிலோ ஜபமாலையிலோ எண்ணிக்கொண்டு, கையைத் துணியால் மூடி ஜபிக்கவும். நான்கு வரிகளின் ஒவ்வொரு முடிவிலும் நிறுத்தவும். கீழே உள்ள எண்ணி உதவும்.`,
      `गायत्री का 108 बार (उत्तम), 28 बार, या कम से कम 10 बार जप करें, उँगलियों या माला पर गिनते हुए, हाथ वस्त्र से ढककर। चारों पंक्तियों में से प्रत्येक के अन्त में रुकें। नीचे का गणक गिनती में सहायक है।`),
    howK: {
      pratah: L(`In the morning, stand (or sit) facing east until the Sun is seen.`, `ಬೆಳಿಗ್ಗೆ ಸೂರ್ಯ ಕಾಣುವವರೆಗೆ ಪೂರ್ವಾಭಿಮುಖವಾಗಿ ನಿಂತು (ಅಥವಾ ಕುಳಿತು) ಜಪಿಸಿ.`, `ఉదయం సూర్యుడు కనిపించే వరకు తూర్పు ముఖంగా నిలబడి (లేదా కూర్చొని) జపించండి.`, `காலையில் சூரியன் தெரியும் வரை கிழக்கு நோக்கி நின்று (அல்லது அமர்ந்து) ஜபிக்கவும்.`, `प्रातः सूर्य दिखने तक पूर्वाभिमुख खड़े होकर (या बैठकर) जप करें।`),
      madhya: L(`At noon, sit facing east.`, `ಮಧ್ಯಾಹ್ನ ಪೂರ್ವಾಭಿಮುಖವಾಗಿ ಕುಳಿತು ಜಪಿಸಿ.`, `మధ్యాహ్నం తూర్పు ముఖంగా కూర్చొని జపించండి.`, `நண்பகலில் கிழக்கு நோக்கி அமர்ந்து ஜபிக்கவும்.`, `मध्याह्न में पूर्वाभिमुख बैठकर जप करें।`),
      sayam: L(`In the evening, sit facing west until the stars appear.`, `ಸಂಜೆ ನಕ್ಷತ್ರಗಳು ಕಾಣುವವರೆಗೆ ಪಶ್ಚಿಮಾಭಿಮುಖವಾಗಿ ಕುಳಿತು ಜಪಿಸಿ.`, `సాయంత్రం నక్షత్రాలు కనిపించే వరకు పడమర ముఖంగా కూర్చొని జపించండి.`, `மாலையில் நட்சத்திரங்கள் தெரியும் வரை மேற்கு நோக்கி அமர்ந்து ஜபிக்கவும்.`, `सायं तारे दिखने तक पश्चिमाभिमुख बैठकर जप करें।`)
    },
    m: [ { d:`सावित्र्या ऋषिर्विश्वामित्रः । देवी गायत्री छन्दः । सविता देवता ॥` },
         { d:`ॐ भूर्भुवस्सुवः ।
तत्सवितुर्वरेण्यम् ।
भर्गो देवस्य धीमहि ।
धियो यो नः प्रचोदयात् ॥` } ],
    mean: MEAN_GAYATRI },

  { id:'udvasana', t:`गायत्र्युपस्थानम्`, ash:'skip',
    how: L(`After japa, do prāṇāyāma, say the saṅkalpa for upasthāna, and bid farewell to the Goddess.`,
      `ಜಪದ ನಂತರ ಪ್ರಾಣಾಯಾಮ ಮಾಡಿ, ಉಪಸ್ಥಾನದ ಸಂಕಲ್ಪ ಹೇಳಿ, ದೇವಿಯನ್ನು ಬೀಳ್ಕೊಡಿ.`,
      `జపం తర్వాత ప్రాణాయామం చేసి, ఉపస్థాన సంకల్పం చెప్పి, దేవిని సాగనంపండి.`,
      `ஜபத்துக்குப் பின் பிராணாயாமம் செய்து, உபஸ்தான சங்கல்பம் சொல்லி, தேவியை வழியனுப்பவும்.`,
      `जप के बाद प्राणायाम करें, उपस्थान का सङ्कल्प बोलें और देवी को विदा करें।`),
    m: [ { k:['pratah'], d: SK + `प्रातस्सन्ध्योपस्थानं करिष्ये ॥` },
         { k:['madhya'], d: SK + `माध्याह्निकोपस्थानं करिष्ये ॥` },
         { k:['sayam'],  d: SK + `सायंसन्ध्योपस्थानं करिष्ये ॥` },
         { d:`उत्तम इत्यनुवाकस्य वामदेव ऋषिः । अनुष्टुप् छन्दः । गायत्री देवता । गायत्र्युद्वासने विनियोगः ॥
उत्तमे शिखरे देवी भूम्यां पर्वतमूर्धनि ।
ब्राह्मणेभ्यो ह्यनुज्ञानं गच्छ देवि यथासुखम् ॥` } ],
    mean: L(`O Goddess, dwelling on the highest peak, on the summit of the mountain on earth: with the leave of the brāhmaṇas, go as you please.`,
      `ಭೂಮಿಯ ಪರ್ವತದ ಶಿಖರದ ಉತ್ತಮ ಶೃಂಗದಲ್ಲಿರುವ ದೇವಿ, ಬ್ರಾಹ್ಮಣರ ಅನುಮತಿಯೊಂದಿಗೆ ಸುಖವಾಗಿ ತೆರಳು.`,
      `భూమిపై పర్వత శిఖరపు ఉత్తమ శృంగంలో ఉండే దేవీ, బ్రాహ్మణుల అనుమతితో సుఖంగా వెళ్ళు.`,
      `பூமியில் மலைச் சிகரத்தின் உயர்ந்த முகட்டில் உறையும் தேவியே, அந்தணர்களின் அனுமதியுடன் இனிதே செல்வாயாக.`,
      `पृथ्वी पर पर्वत के शिखर के उत्तम शृङ्ग पर स्थित हे देवी, ब्राह्मणों की अनुमति से सुखपूर्वक जाओ।`) },

  { id:'upasthana', t:`सूर्योपस्थानम्`, ash:'skip',
    how: L(`Stand facing the Sun with folded hands and recite the upasthāna.`, `ಕೈ ಮುಗಿದು ಸೂರ್ಯನ ಕಡೆಗೆ ನಿಂತು ಉಪಸ್ಥಾನ ಹೇಳಿ.`, `చేతులు జోడించి సూర్యుని వైపు నిలబడి ఉపస్థానం చెప్పండి.`, `கைகூப்பிச் சூரியனை நோக்கி நின்று உபஸ்தானம் சொல்லவும்.`, `हाथ जोड़कर सूर्य की ओर खड़े होकर उपस्थान करें।`),
    howK: {
      pratah: L(`Morning: the hymns to Mitra, facing east.`, `ಬೆಳಿಗ್ಗೆ: ಮಿತ್ರ ಸ್ತುತಿ, ಪೂರ್ವಾಭಿಮುಖವಾಗಿ.`, `ఉదయం: మిత్ర స్తుతి, తూర్పు ముఖంగా.`, `காலை: மித்ர துதி, கிழக்கு நோக்கி.`, `प्रातः: मित्र स्तुति, पूर्वाभिमुख।`),
      madhya: L(`Noon: the hymns to Āditya, facing the Sun.`, `ಮಧ್ಯಾಹ್ನ: ಆದಿತ್ಯ ಸ್ತುತಿ, ಸೂರ್ಯನ ಕಡೆಗೆ.`, `మధ్యాహ్నం: ఆదిత్య స్తుతి, సూర్యుని వైపు.`, `நண்பகல்: ஆதித்ய துதி, சூரியனை நோக்கி.`, `मध्याह्न: आदित्य स्तुति, सूर्य की ओर।`),
      sayam: L(`Evening: the hymns to Varuṇa, facing west.`, `ಸಂಜೆ: ವರುಣ ಸ್ತುತಿ, ಪಶ್ಚಿಮಾಭಿಮುಖವಾಗಿ.`, `సాయంత్రం: వరుణ స్తుతి, పడమర ముఖంగా.`, `மாலை: வருண துதி, மேற்கு நோக்கி.`, `सायं: वरुण स्तुति, पश्चिमाभिमुख।`)
    },
    m: [ { k:['pratah'], d:`मित्रस्य चर्षणीधृतः श्रवो देवस्य सानसिम् । सत्यं चित्रश्रवस्तमम् ॥
मित्रो जनान् यातयति प्रजानन् मित्रो दाधार पृथिवीमुत द्याम् ।
मित्रः कृष्टीरनिमिषाऽभिचष्टे सत्याय हव्यं घृतवद्विधेम ॥
प्र स मित्र मर्तो अस्तु प्रयस्वान् यस्त आदित्य शिक्षति व्रतेन ।
न हन्यते न जीयते त्वोतो नैनमग्ंहो अश्नोत्यन्तितो न दूरात् ॥` },
         { k:['madhya'], d:`आ सत्येन रजसा वर्तमानो निवेशयन्नमृतं मर्त्यं च ।
हिरण्ययेन सविता रथेना देवो याति भुवना विपश्यन् ॥
उद्वयं तमसस्परि पश्यन्तो ज्योतिरुत्तरम् ।
देवं देवत्रा सूर्यमगन्म ज्योतिरुत्तमम् ॥
उदु त्यं जातवेदसं देवं वहन्ति केतवः । दृशे विश्वाय सूर्यम् ॥
चित्रं देवानामुदगादनीकं चक्षुर्मित्रस्य वरुणस्याग्नेः ।
आप्रा द्यावापृथिवी अन्तरिक्षग्ं सूर्य आत्मा जगतस्तस्थुषश्च ॥
तच्चक्षुर्देवहितं पुरस्ताच्छुक्रमुच्चरत् ।
पश्येम शरदश्शतम् । जीवेम शरदश्शतम् । नन्दाम शरदश्शतम् ।
मोदाम शरदश्शतम् । भवाम शरदश्शतम् । शृणवाम शरदश्शतम् ।
प्रब्रवाम शरदश्शतम् । अजीतास्याम शरदश्शतम् । ज्योक्च सूर्यं दृशे ॥
य उदगान्महतोऽर्णवाद्विभ्राजमानः सरिरस्य मध्यात् ।
स मा वृषभो लोहिताक्षस्सूर्यो विपश्चिन्मनसा पुनातु ॥` },
         { k:['sayam'], d:`इमं मे वरुण श्रुधी हवमद्या च मृडय । त्वामवस्युराचके ॥
तत्त्वा यामि ब्रह्मणा वन्दमानस्तदाशास्ते यजमानो हविर्भिः ।
अहेडमानो वरुणेह बोध्युरुशग्ंस मा न आयुः प्रमोषीः ॥
यच्चिद्धि ते विशो यथा प्र देव वरुण व्रतम् । मिनीमसि द्यविद्यवि ॥
यत्किञ्चेदं वरुण दैव्ये जनेऽभिद्रोहं मनुष्याश्चरामसि ।
अचित्ती यत्तव धर्मा युयोपिम मा नस्तस्मादेनसो देव रीरिषः ॥
कितवासो यद्रिरिपुर्न दीवि यद्वा घा सत्यमुत यन्न विद्म ।
सर्वा ता विष्य शिथिरेव देवाथा ते स्याम वरुण प्रियासः ॥` } ],
    meanK: {
      pratah: L(`We praise the glory of Mitra, who sustains mankind; his fame is true and most wonderful. Mitra guides people, upholds the earth and the sky, and watches all beings without blinking. The mortal who serves you faithfully, O Āditya, prospers; protected by you he is never slain or overcome, and no evil reaches him from near or far.`,
        `ಮನುಷ್ಯರನ್ನು ಪೋಷಿಸುವ ಮಿತ್ರನ ಕೀರ್ತಿಯನ್ನು ಸ್ತುತಿಸುತ್ತೇವೆ; ಅವನ ಯಶಸ್ಸು ಸತ್ಯವಾದುದು, ಅತ್ಯಂತ ಅದ್ಭುತವಾದುದು. ಮಿತ್ರನು ಜನರನ್ನು ಮುನ್ನಡೆಸುತ್ತಾನೆ, ಭೂಮಿ ಆಕಾಶಗಳನ್ನು ಧರಿಸುತ್ತಾನೆ, ಕಣ್ಣು ಮಿಟುಕಿಸದೆ ಎಲ್ಲರನ್ನೂ ನೋಡುತ್ತಾನೆ. ಓ ಆದಿತ್ಯ, ನಿನ್ನನ್ನು ವ್ರತದಿಂದ ಆರಾಧಿಸುವವನು ಸಮೃದ್ಧನಾಗುತ್ತಾನೆ; ನಿನ್ನ ರಕ್ಷಣೆಯಲ್ಲಿ ಅವನು ಕೊಲ್ಲಲ್ಪಡುವುದಿಲ್ಲ, ಸೋಲುವುದಿಲ್ಲ, ಹತ್ತಿರದಿಂದಾಗಲೀ ದೂರದಿಂದಾಗಲೀ ಪಾಪ ಅವನನ್ನು ತಲುಪದು.`,
        `మానవులను పోషించే మిత్రుని కీర్తిని స్తుతిస్తున్నాము; అతని యశస్సు సత్యమైనది, అత్యంత అద్భుతమైనది. మిత్రుడు జనులను నడిపిస్తాడు, భూమ్యాకాశాలను ధరిస్తాడు, రెప్ప వేయకుండా అందరినీ చూస్తాడు. ఓ ఆదిత్యా, వ్రతంతో నిన్ను సేవించేవాడు వర్ధిల్లుతాడు; నీ రక్షణలో అతడు చంపబడడు, ఓడిపోడు, దగ్గర నుండైనా దూరం నుండైనా పాపం అతనిని చేరదు.`,
        `மனிதர்களைக் காக்கும் மித்ரனின் புகழைத் துதிக்கிறோம்; அவன் புகழ் உண்மையானது, மிக அற்புதமானது. மித்ரன் மக்களை வழிநடத்துகிறான், பூமியையும் வானையும் தாங்குகிறான், இமைக்காமல் எல்லோரையும் காண்கிறான். ஆதித்யனே, விரதத்துடன் உன்னை வழிபடுபவன் செழிக்கிறான்; உன் காவலில் அவன் கொல்லப்படுவதில்லை, தோற்பதில்லை, அருகிலிருந்தோ தொலைவிலிருந்தோ பாவம் அவனை அணுகாது.`,
        `मनुष्यों का पालन करने वाले मित्र की कीर्ति की हम स्तुति करते हैं; उनका यश सत्य और अत्यन्त अद्भुत है। मित्र लोगों को मार्ग दिखाते हैं, पृथ्वी और आकाश को धारण करते हैं, और बिना पलक झपकाए सबको देखते हैं। हे आदित्य, जो व्रत से तुम्हारी सेवा करता है वह समृद्ध होता है; तुमसे रक्षित वह न मारा जाता है, न पराजित होता है, पास या दूर से पाप उसे नहीं छूता।`),
      madhya: L(`The divine Savitṛ comes on his golden chariot, setting the immortal and the mortal in their places and beholding the worlds. Rising above the darkness we reach the Sun, the highest light. That eye, dear to the gods, rises bright in the east: may we see a hundred autumns, live, rejoice, delight, flourish, hear and speak for a hundred autumns, unconquered, and long behold the Sun. May the Sun, the red-eyed bull who rose shining from the great ocean, purify me in mind.`,
        `ಸವಿತೃ ದೇವನು ಅಮೃತ ಮತ್ತು ಮರ್ತ್ಯರನ್ನು ಅವರವರ ಸ್ಥಾನದಲ್ಲಿರಿಸುತ್ತಾ, ಲೋಕಗಳನ್ನು ನೋಡುತ್ತಾ ಚಿನ್ನದ ರಥದಲ್ಲಿ ಬರುತ್ತಾನೆ. ಕತ್ತಲೆಯನ್ನು ದಾಟಿ ಉತ್ತಮ ಜ್ಯೋತಿಯಾದ ಸೂರ್ಯನನ್ನು ಸೇರುತ್ತೇವೆ. ದೇವತೆಗಳಿಗೆ ಪ್ರಿಯವಾದ ಆ ಕಣ್ಣು ಪೂರ್ವದಲ್ಲಿ ಪ್ರಕಾಶಮಾನವಾಗಿ ಉದಯಿಸುತ್ತದೆ: ನೂರು ಶರತ್ತುಗಳು ನೋಡೋಣ, ಬದುಕೋಣ, ಆನಂದಿಸೋಣ, ಕೇಳೋಣ, ಮಾತನಾಡೋಣ, ಸೋಲಿಲ್ಲದವರಾಗಿರೋಣ, ಬಹುಕಾಲ ಸೂರ್ಯನನ್ನು ಕಾಣೋಣ. ಮಹಾಸಾಗರದಿಂದ ಪ್ರಕಾಶಿಸುತ್ತಾ ಉದಯಿಸಿದ ಕೆಂಪುಕಣ್ಣಿನ ವೃಷಭನಾದ ಸೂರ್ಯನು ನನ್ನ ಮನಸ್ಸನ್ನು ಶುದ್ಧಗೊಳಿಸಲಿ.`,
        `సవితృ దేవుడు అమృతులను మర్త్యులను వారి వారి స్థానాల్లో ఉంచుతూ, లోకాలను చూస్తూ బంగారు రథంపై వస్తాడు. చీకటిని దాటి ఉత్తమ జ్యోతియైన సూర్యుని చేరుతాము. దేవతలకు ప్రియమైన ఆ నేత్రం తూర్పున ప్రకాశంగా ఉదయిస్తుంది: నూరు శరత్తులు చూద్దాం, జీవిద్దాం, ఆనందిద్దాం, విందాం, మాట్లాడుదాం, ఓటమి లేకుండా ఉందాం, చిరకాలం సూర్యుని చూద్దాం. మహాసముద్రం నుండి ప్రకాశిస్తూ ఉదయించిన ఎర్రని కన్నుల వృషభమైన సూర్యుడు నా మనసును పవిత్రం చేయుగాక.`,
        `ஸவித்ரு தேவன் அமரர்களையும் மனிதர்களையும் அவரவர் இடத்தில் நிறுத்தி, உலகங்களைப் பார்த்தபடி பொன் தேரில் வருகிறான். இருளைக் கடந்து உயர்ந்த ஒளியான சூரியனை அடைகிறோம். தேவர்களுக்கு இனிய அந்தக் கண் கிழக்கில் ஒளிர்ந்து எழுகிறது: நூறு ஆண்டுகள் காண்போம், வாழ்வோம், மகிழ்வோம், கேட்போம், பேசுவோம், வெல்லப்படாதிருப்போம், நெடுநாள் சூரியனைக் காண்போம். பெருங்கடலிலிருந்து ஒளிர்ந்து எழுந்த சிவந்த கண்களுடைய காளையான சூரியன் என் மனத்தைத் தூய்மைப்படுத்தட்டும்.`,
        `सविता देव अमृत और मर्त्य को अपने-अपने स्थान पर रखते हुए, लोकों को देखते हुए स्वर्ण रथ पर आते हैं। अन्धकार से ऊपर उठकर हम उत्तम ज्योति सूर्य को प्राप्त होते हैं। देवों का प्रिय वह नेत्र पूर्व में उज्ज्वल उदित होता है: हम सौ शरद् देखें, जीएँ, आनन्दित हों, सुनें, बोलें, अपराजित रहें, और चिरकाल सूर्य को देखें। महासागर से दीप्त होकर उदित लाल नेत्रों वाले वृषभ सूर्य मेरे मन को पवित्र करें।`),
      sayam: L(`Hear my call, O Varuṇa, and be gracious to us today; seeking your protection I call on you. Whatever offence we humans commit against the divine host, whatever of your laws we break through thoughtlessness, do not harm us for that sin. Loosen all our faults, as one unties a knot, and may we be dear to you, O Varuṇa.`,
        `ಓ ವರುಣ, ನನ್ನ ಕರೆಯನ್ನು ಕೇಳು, ಇಂದು ನಮಗೆ ಕೃಪೆ ತೋರು; ರಕ್ಷಣೆಯನ್ನು ಬಯಸಿ ನಿನ್ನನ್ನು ಕರೆಯುತ್ತೇನೆ. ಮನುಷ್ಯರಾದ ನಾವು ದೇವತೆಗಳ ವಿರುದ್ಧ ಮಾಡುವ ಯಾವುದೇ ಅಪರಾಧ, ಅಜ್ಞಾನದಿಂದ ನಿನ್ನ ಧರ್ಮವನ್ನು ಮೀರಿದ್ದು, ಆ ಪಾಪಕ್ಕಾಗಿ ನಮ್ಮನ್ನು ಹಿಂಸಿಸಬೇಡ. ಗಂಟನ್ನು ಬಿಚ್ಚುವಂತೆ ಎಲ್ಲ ದೋಷಗಳನ್ನು ಸಡಿಲಿಸು; ಓ ವರುಣ, ನಾವು ನಿನಗೆ ಪ್ರಿಯರಾಗೋಣ.`,
        `ఓ వరుణా, నా పిలుపు విను, ఈరోజు మాపై దయ చూపు; రక్షణ కోరి నిన్ను పిలుస్తున్నాను. మానవులమైన మేము దేవతల పట్ల చేసే ఏ అపరాధమైనా, అజ్ఞానంతో నీ ధర్మాన్ని అతిక్రమించినదైనా, ఆ పాపానికి మమ్మల్ని హింసించకు. ముడి విప్పినట్లు అన్ని దోషాలను సడలించు; ఓ వరుణా, మేము నీకు ప్రియులమగుదుము.`,
        `வருணனே, என் அழைப்பைக் கேள், இன்று எங்களுக்கு அருள்புரி; காவலை நாடி உன்னை அழைக்கிறேன். மனிதர்களாகிய நாங்கள் தேவர்களுக்கு எதிராகச் செய்யும் எந்தக் குற்றமும், அறியாமையால் உன் நெறியை மீறியதும், அந்தப் பாவத்துக்காக எங்களைத் துன்புறுத்தாதே. முடிச்சை அவிழ்ப்பது போல் எல்லாக் குற்றங்களையும் தளர்த்து; வருணனே, நாங்கள் உனக்கு அன்புக்குரியவர்களாவோமாக.`,
        `हे वरुण, मेरी पुकार सुनो और आज हम पर कृपा करो; रक्षा की इच्छा से मैं तुम्हें पुकारता हूँ। हम मनुष्य देवों के प्रति जो भी अपराध करें, अज्ञान से तुम्हारे धर्म का जो उल्लंघन करें, उस पाप के लिए हमें दण्ड न दो। गाँठ खोलने की भाँति सब दोष ढीले करो; हे वरुण, हम तुम्हारे प्रिय बनें।`) } },

  { id:'abhivadana', t:`समष्ट्यभिवादनम्`, ash:'skip',
    how: L(`Bow to the deities of Sandhyā. Then, touching both ears, say the abhivādana with your own pravara, gotra, sūtra and name in place of the dots, and bow.`,
      `ಸಂಧ್ಯಾ ದೇವತೆಗಳಿಗೆ ನಮಸ್ಕರಿಸಿ. ನಂತರ ಎರಡೂ ಕಿವಿಗಳನ್ನು ಮುಟ್ಟಿ, ಚುಕ್ಕೆಗಳ ಜಾಗದಲ್ಲಿ ನಿಮ್ಮ ಪ್ರವರ, ಗೋತ್ರ, ಸೂತ್ರ, ಹೆಸರನ್ನು ಹೇಳಿ ಅಭಿವಾದನ ಮಾಡಿ ನಮಸ್ಕರಿಸಿ.`,
      `సంధ్యా దేవతలకు నమస్కరించండి. తర్వాత రెండు చెవులను తాకి, చుక్కల స్థానంలో మీ ప్రవర, గోత్రం, సూత్రం, పేరు చెప్పి అభివాదనం చేసి నమస్కరించండి.`,
      `சந்தியா தேவதைகளுக்கு நமஸ்கரிக்கவும். பிறகு இரு காதுகளையும் தொட்டு, புள்ளிகளின் இடத்தில் உங்கள் ப்ரவரம், கோத்ரம், ஸூத்ரம், பெயரைச் சொல்லி அபிவாதனம் செய்து நமஸ்கரிக்கவும்.`,
      `सन्ध्या देवताओं को नमस्कार करें। फिर दोनों कान छूकर, बिन्दुओं के स्थान पर अपना प्रवर, गोत्र, सूत्र और नाम बोलकर अभिवादन करें और प्रणाम करें।`),
    m: [ { d:`सन्ध्यायै नमः । सावित्र्यै नमः । गायत्र्यै नमः । सरस्वत्यै नमः ।
सर्वाभ्यो देवताभ्यो नमो नमः । कामोऽकार्षीन्मन्युरकार्षीन्नमो नमः ॥` },
         { d:`अभिवादये … त्रयार्षेय प्रवरान्वित … गोत्रः आपस्तम्बसूत्रः यजुश्शाखाध्यायी … शर्मा नामाहं अस्मि भोः ॥` } ],
    mean: L(`Salutations to Sandhyā, Sāvitrī, Gāyatrī, Sarasvatī and all the deities. Desire did it, anger did it: salutations. In the abhivādana you announce your lineage: "I, of such a pravara and gotra, of the Āpastamba sūtra, a student of the Yajus branch, named so-and-so, salute you."`,
      `ಸಂಧ್ಯಾ, ಸಾವಿತ್ರೀ, ಗಾಯತ್ರೀ, ಸರಸ್ವತೀ ಮತ್ತು ಎಲ್ಲ ದೇವತೆಗಳಿಗೆ ನಮಸ್ಕಾರ. ಕಾಮ ಮಾಡಿಸಿತು, ಕೋಪ ಮಾಡಿಸಿತು: ನಮಸ್ಕಾರ. ಅಭಿವಾದನದಲ್ಲಿ ನಿಮ್ಮ ವಂಶವನ್ನು ಹೇಳುತ್ತೀರಿ: "ಇಂತಹ ಪ್ರವರ, ಗೋತ್ರದ, ಆಪಸ್ತಂಬ ಸೂತ್ರದ, ಯಜುಶ್ಶಾಖಾಧ್ಯಾಯಿ, ಇಂತಹ ಹೆಸರಿನವನಾದ ನಾನು ನಮಸ್ಕರಿಸುತ್ತೇನೆ."`,
      `సంధ్య, సావిత్రి, గాయత్రి, సరస్వతి మరియు సర్వ దేవతలకు నమస్కారం. కామం చేయించింది, కోపం చేయించింది: నమస్కారం. అభివాదనంలో మీ వంశాన్ని చెబుతారు: "ఫలానా ప్రవర, గోత్రం గల, ఆపస్తంబ సూత్రం, యజుశ్శాఖాధ్యాయి, ఫలానా పేరు గల నేను నమస్కరిస్తున్నాను."`,
      `ஸந்தியா, ஸாவித்ரி, காயத்ரி, ஸரஸ்வதி மற்றும் எல்லாத் தேவதைகளுக்கும் நமஸ்காரம். காமம் செய்வித்தது, கோபம் செய்வித்தது: நமஸ்காரம். அபிவாதனத்தில் உங்கள் வம்சத்தைச் சொல்கிறீர்கள்: "இன்ன ப்ரவரம், கோத்ரம் உடைய, ஆபஸ்தம்ப ஸூத்ரம், யஜுச்சாகை அத்யாயியான, இன்ன பெயருடைய நான் வணங்குகிறேன்."`,
      `सन्ध्या, सावित्री, गायत्री, सरस्वती और सब देवताओं को नमस्कार। काम ने किया, मन्यु ने किया: नमस्कार। अभिवादन में आप अपना वंश बताते हैं: "अमुक प्रवर और गोत्र का, आपस्तम्ब सूत्र का, यजुश्शाखाध्यायी, अमुक नाम वाला मैं प्रणाम करता हूँ।"`) },

  { id:'dik', t:`दिग्देवतावन्दनम्`, ash:'skip',
    how: L(`Turn and bow to each direction in turn, then upwards, downwards, to the sky, the earth and the deities.`,
      `ಪ್ರತಿ ದಿಕ್ಕಿನ ಕಡೆಗೆ ತಿರುಗಿ ನಮಸ್ಕರಿಸಿ, ನಂತರ ಮೇಲೆ, ಕೆಳಗೆ, ಅಂತರಿಕ್ಷ, ಭೂಮಿ ಮತ್ತು ದೇವತೆಗಳಿಗೆ.`,
      `ఒక్కొక్క దిక్కు వైపు తిరిగి నమస్కరించండి, తర్వాత పైకి, క్రిందికి, అంతరిక్షానికి, భూమికి, దేవతలకు.`,
      `ஒவ்வொரு திசையையும் நோக்கித் திரும்பி வணங்கவும், பிறகு மேலே, கீழே, அந்தரிக்ஷம், பூமி, தேவதைகளுக்கு.`,
      `प्रत्येक दिशा की ओर मुड़कर प्रणाम करें, फिर ऊपर, नीचे, अन्तरिक्ष, पृथ्वी और देवताओं को।`),
    howK: { sayam: L(`In the evening, begin with the west.`, `ಸಂಜೆ ಪಶ್ಚಿಮದಿಂದ ಆರಂಭಿಸಿ.`, `సాయంత్రం పడమర నుండి ప్రారంభించండి.`, `மாலையில் மேற்கிலிருந்து தொடங்கவும்.`, `सायंकाल पश्चिम से आरम्भ करें।`) },
    m: [ { k:['pratah','madhya'], d:`प्राच्यै दिशे नमः । दक्षिणायै दिशे नमः । प्रतीच्यै दिशे नमः । उदीच्यै दिशे नमः ।` },
         { k:['sayam'], d:`प्रतीच्यै दिशे नमः । उदीच्यै दिशे नमः । प्राच्यै दिशे नमः । दक्षिणायै दिशे नमः ।` },
         { d:`ऊर्ध्वाय नमः । अधराय नमः । अन्तरिक्षाय नमः । भूम्यै नमः ।
ब्रह्मणे नमः । विष्णवे नमः । रुद्राय नमः ॥` } ],
    mean: L(`Salutations to the east, south, west and north, to above and below, to the sky and the earth, and to Brahmā, Viṣṇu and Rudra.`,
      `ಪೂರ್ವ, ದಕ್ಷಿಣ, ಪಶ್ಚಿಮ, ಉತ್ತರ ದಿಕ್ಕುಗಳಿಗೆ, ಮೇಲೆ ಕೆಳಗೆ, ಅಂತರಿಕ್ಷ ಭೂಮಿಗಳಿಗೆ, ಬ್ರಹ್ಮ, ವಿಷ್ಣು, ರುದ್ರರಿಗೆ ನಮಸ್ಕಾರ.`,
      `తూర్పు, దక్షిణం, పడమర, ఉత్తర దిక్కులకు, పైకి క్రిందికి, అంతరిక్ష భూములకు, బ్రహ్మ, విష్ణు, రుద్రులకు నమస్కారం.`,
      `கிழக்கு, தெற்கு, மேற்கு, வடக்குத் திசைகளுக்கும், மேல் கீழுக்கும், அந்தரிக்ஷம் பூமிக்கும், பிரம்மா, விஷ்ணு, ருத்ரனுக்கும் நமஸ்காரம்.`,
      `पूर्व, दक्षिण, पश्चिम, उत्तर दिशाओं को, ऊपर-नीचे को, अन्तरिक्ष और पृथ्वी को, तथा ब्रह्मा, विष्णु और रुद्र को नमस्कार।`) },

  { id:'yama', t:`यमवन्दनम्`, ash:'skip',
    how: L(`Face south and bow to Yama, the lord of dharma.`, `ದಕ್ಷಿಣಾಭಿಮುಖವಾಗಿ ಧರ್ಮರಾಜ ಯಮನಿಗೆ ನಮಸ್ಕರಿಸಿ.`, `దక్షిణ ముఖంగా ధర్మరాజైన యమునికి నమస్కరించండి.`, `தெற்கு நோக்கித் தர்மராஜனான யமனை வணங்கவும்.`, `दक्षिणाभिमुख होकर धर्मराज यम को प्रणाम करें।`),
    m: [ { d:`यमाय धर्मराजाय मृत्यवे चान्तकाय च ।
वैवस्वताय कालाय सर्वभूतक्षयाय च ॥
औदुम्बराय दध्नाय नीलाय परमेष्ठिने ।
वृकोदराय चित्राय चित्रगुप्ताय वै नमः ॥
चित्रगुप्ताय वै नम ओं नम इति ॥` } ],
    mean: L(`Salutations to Yama, king of dharma, Death, the Ender, son of Vivasvān, Time, destroyer of all beings; to Audumbara, Dadhna, Nīla, Parameṣṭhin, Vṛkodara, Citra and Citragupta.`,
      `ಧರ್ಮರಾಜ, ಮೃತ್ಯು, ಅಂತಕ, ವೈವಸ್ವತ, ಕಾಲ, ಸರ್ವಭೂತಕ್ಷಯಕರನಾದ ಯಮನಿಗೆ; ಔದುಂಬರ, ದಧ್ನ, ನೀಲ, ಪರಮೇಷ್ಠಿ, ವೃಕೋದರ, ಚಿತ್ರ, ಚಿತ್ರಗುಪ್ತರಿಗೆ ನಮಸ್ಕಾರ.`,
      `ధర్మరాజు, మృత్యువు, అంతకుడు, వైవస్వతుడు, కాలుడు, సర్వభూతక్షయకారుడైన యమునికి; ఔదుంబర, దధ్న, నీల, పరమేష్ఠి, వృకోదర, చిత్ర, చిత్రగుప్తులకు నమస్కారం.`,
      `தர்மராஜன், ம்ருத்யு, அந்தகன், வைவஸ்வதன், காலன், எல்லா உயிர்களையும் அழிப்பவனான யமனுக்கு; ஔதும்பரன், தத்னன், நீலன், பரமேஷ்டி, வ்ருகோதரன், சித்ரன், சித்ரகுப்தனுக்கு நமஸ்காரம்.`,
      `धर्मराज, मृत्यु, अन्तक, वैवस्वत, काल, सर्वभूतक्षयकारी यम को; औदुम्बर, दध्न, नील, परमेष्ठी, वृकोदर, चित्र और चित्रगुप्त को नमस्कार।`) },

  { id:'harihara', t:`विश्वरूपवन्दनम्`, ash:'skip',
    how: L(`Bow to the Supreme as Śiva, the cosmic form.`, `ವಿಶ್ವರೂಪನಾದ ಪರಮಶಿವನಿಗೆ ನಮಸ್ಕರಿಸಿ.`, `విశ్వరూపుడైన పరమశివునికి నమస్కరించండి.`, `விஸ்வரூபனான பரமசிவனை வணங்கவும்.`, `विश्वरूप परमशिव को प्रणाम करें।`),
    m: [ { d:`ऋतग्ं सत्यं परं ब्रह्म पुरुषं कृष्णपिङ्गलम् ।
ऊर्ध्वरेतं विरूपाक्षं विश्वरूपाय वै नमो नमः ॥
विश्वरूपाय वै नम ओं नम इति ॥` } ],
    mean: L(`Salutations to the cosmic form: Order, Truth, the supreme Brahman, the Person, dark and tawny, chaste, with uneven (three) eyes.`,
      `ಋತ, ಸತ್ಯ, ಪರಬ್ರಹ್ಮ, ಕೃಷ್ಣಪಿಂಗಲ ವರ್ಣದ ಪುರುಷ, ಊರ್ಧ್ವರೇತಸ್, ವಿರೂಪಾಕ್ಷನಾದ ವಿಶ್ವರೂಪನಿಗೆ ನಮಸ್ಕಾರ.`,
      `ఋతం, సత్యం, పరబ్రహ్మం, కృష్ణపింగళ వర్ణ పురుషుడు, ఊర్ధ్వరేతస్సు, విరూపాక్షుడైన విశ్వరూపునికి నమస్కారం.`,
      `ருதம், ஸத்யம், பரப்பிரம்மம், கருமையும் பொன்மையும் கலந்த புருஷன், ஊர்த்வரேதஸ், விரூபாக்ஷனான விஸ்வரூபனுக்கு நமஸ்காரம்.`,
      `ऋत, सत्य, परब्रह्म, कृष्णपिङ्गल वर्ण पुरुष, ऊर्ध्वरेता, विरूपाक्ष विश्वरूप को नमस्कार।`) },

  { id:'narmada', t:`नर्मदासर्पवन्दनम्`, ash:'skip', opt:true,
    how: L(`Many Tamil Smārta families add this prayer for protection from snakes.`, `ಹಲವು ತಮಿಳು ಸ್ಮಾರ್ತ ಮನೆತನಗಳು ಸರ್ಪಭಯ ನಿವಾರಣೆಗೆ ಈ ಪ್ರಾರ್ಥನೆಯನ್ನು ಸೇರಿಸುತ್ತಾರೆ.`, `చాలా తమిళ స్మార్త కుటుంబాలు సర్పభయ నివారణకు ఈ ప్రార్థనను చేరుస్తారు.`, `பல தமிழ் ஸ்மார்த்தக் குடும்பங்கள் பாம்பு பயம் நீங்க இந்தப் பிரார்த்தனையைச் சேர்ப்பர்.`, `बहुत से तमिल स्मार्त परिवार सर्पभय निवारण के लिए यह प्रार्थना जोड़ते हैं।`),
    m: [ { d:`नर्मदायै नमः प्रातर्नर्मदायै नमो निशि ।
नमोऽस्तु नर्मदे तुभ्यं त्राहि मां विषसर्पतः ॥
अपसर्प सर्प भद्रं ते दूरं गच्छ महायशः ।
जनमेजयस्य यज्ञान्ते आस्तीकवचनं स्मरन् ॥
जरत्कारोर्जरत्कार्वां समुत्पन्नो महायशाः ।
आस्तीकस्सत्यसन्धो मां पन्नगेभ्योऽभिरक्षतु ॥
पन्नगेभ्योऽभिरक्षतु ओं नम इति ॥` } ],
    mean: L(`Salutations to Narmadā at dawn and at night; protect me from venomous snakes. Go away, O snake, remembering Āstīka's words at the end of Janamejaya's sacrifice. May truthful Āstīka, born of Jaratkāru and his wife Jaratkārū, protect me from serpents.`,
      `ಬೆಳಿಗ್ಗೆ ರಾತ್ರಿ ನರ್ಮದೆಗೆ ನಮಸ್ಕಾರ; ವಿಷಸರ್ಪಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸು. ಓ ಸರ್ಪವೇ, ಜನಮೇಜಯನ ಯಜ್ಞದ ಕೊನೆಯ ಆಸ್ತೀಕನ ಮಾತನ್ನು ನೆನೆದು ದೂರ ಹೋಗು. ಜರತ್ಕಾರು ದಂಪತಿಗಳ ಮಗನಾದ ಸತ್ಯಸಂಧ ಆಸ್ತೀಕನು ಸರ್ಪಗಳಿಂದ ನನ್ನನ್ನು ರಕ್ಷಿಸಲಿ.`,
      `ఉదయం రాత్రి నర్మదకు నమస్కారం; విషసర్పాల నుండి నన్ను రక్షించు. ఓ సర్పమా, జనమేజయుని యజ్ఞాంతంలో ఆస్తీకుని మాట తలచుకొని దూరంగా వెళ్ళు. జరత్కారు దంపతుల పుత్రుడైన సత్యసంధుడు ఆస్తీకుడు సర్పాల నుండి నన్ను రక్షించుగాక.`,
      `காலையிலும் இரவிலும் நர்மதைக்கு நமஸ்காரம்; விஷப் பாம்புகளிடமிருந்து என்னைக் காப்பாற்று. பாம்பே, ஜனமேஜயனின் யாகத்தின் முடிவில் ஆஸ்தீகர் சொன்னதை நினைத்து விலகிச் செல். ஜரத்காரு தம்பதியரின் மகனான சத்தியம் தவறாத ஆஸ்தீகர் பாம்புகளிடமிருந்து என்னைக் காக்கட்டும்.`,
      `प्रातः और रात्रि में नर्मदा को नमस्कार; विषैले सर्पों से मेरी रक्षा करो। हे सर्प, जनमेजय के यज्ञ के अन्त में आस्तीक के वचन का स्मरण करके दूर चले जाओ। जरत्कारु दम्पती के पुत्र सत्यसन्ध आस्तीक सर्पों से मेरी रक्षा करें।`) },

  { id:'suryanarayana', t:`सूर्यनारायणवन्दनम्`, ash:'skip',
    how: L(`Face the Sun and bow to Sūrya-Nārāyaṇa. Then say the abhivādana again (step 23) and prostrate.`,
      `ಸೂರ್ಯನ ಕಡೆಗೆ ತಿರುಗಿ ಸೂರ್ಯನಾರಾಯಣನಿಗೆ ನಮಸ್ಕರಿಸಿ. ನಂತರ ಮತ್ತೆ ಅಭಿವಾದನ (ಹಂತ 23) ಹೇಳಿ ಸಾಷ್ಟಾಂಗ ನಮಸ್ಕಾರ ಮಾಡಿ.`,
      `సూర్యుని వైపు తిరిగి సూర్యనారాయణునికి నమస్కరించండి. తర్వాత మళ్ళీ అభివాదనం (దశ 23) చెప్పి సాష్టాంగ నమస్కారం చేయండి.`,
      `சூரியனை நோக்கித் திரும்பி சூர்யநாராயணனை வணங்கவும். பிறகு மீண்டும் அபிவாதனம் (படி 23) சொல்லி சாஷ்டாங்க நமஸ்காரம் செய்யவும்.`,
      `सूर्य की ओर मुड़कर सूर्यनारायण को प्रणाम करें। फिर पुनः अभिवादन (चरण 23) बोलकर साष्टाङ्ग प्रणाम करें।`),
    m: [ { d:`नमः सवित्रे जगदेकचक्षुषे जगत्प्रसूतिस्थितिनाशहेतवे ।
त्रयीमयाय त्रिगुणात्मधारिणे विरिञ्चिनारायणशङ्करात्मने ॥` },
         { d:`ध्येयः सदा सवितृमण्डलमध्यवर्ती नारायणः सरसिजासनसन्निविष्टः ।
केयूरवान् मकरकुण्डलवान् किरीटी हारी हिरण्मयवपुर्धृतशङ्खचक्रः ॥` },
         { d:`शङ्खचक्रगदापाणे द्वारकानिलयाच्युत ।
गोविन्द पुण्डरीकाक्ष रक्ष मां शरणागतम् ॥` },
         { d:`आकाशात्पतितं तोयं यथा गच्छति सागरम् ।
सर्वदेवनमस्कारः केशवं प्रति गच्छति ॥
श्रीकेशवं प्रति गच्छत्योन्नम इति ॥` },
         { d:`वासनाद्वासुदेवस्य वासितं ते जगत्त्रयम् ।
सर्वभूतनिवासोऽसि श्रीवासुदेव नमोऽस्तु ते ॥` },
         { d:`नमो ब्रह्मण्यदेवाय गोब्राह्मणहिताय च ।
जगद्धिताय कृष्णाय गोविन्दाय नमो नमः ॥` } ],
    mean: L(`Salutations to Savitṛ, the one eye of the world, cause of its creation, sustenance and dissolution, made of the three Vedas, bearing the three guṇas, whose self is Brahmā, Nārāyaṇa and Śaṅkara. Nārāyaṇa, seated on a lotus in the orb of the Sun, golden, with armlets, fish-shaped earrings, crown and necklace, holding conch and discus, should always be meditated upon. As rain falling from the sky goes to the ocean, every salutation to any god reaches Keśava.`,
      `ಜಗತ್ತಿನ ಏಕೈಕ ನೇತ್ರ, ಸೃಷ್ಟಿ ಸ್ಥಿತಿ ಲಯಗಳ ಕಾರಣ, ತ್ರಯೀಮಯ, ತ್ರಿಗುಣಧಾರಿ, ಬ್ರಹ್ಮ ನಾರಾಯಣ ಶಂಕರ ಸ್ವರೂಪನಾದ ಸವಿತೃವಿಗೆ ನಮಸ್ಕಾರ. ಸೂರ್ಯಮಂಡಲದ ಮಧ್ಯದಲ್ಲಿ ಕಮಲಾಸನದಲ್ಲಿ ಕುಳಿತ, ಕೇಯೂರ, ಮಕರಕುಂಡಲ, ಕಿರೀಟ, ಹಾರಧಾರಿ, ಸುವರ್ಣದೇಹಿ, ಶಂಖಚಕ್ರಧಾರಿ ನಾರಾಯಣನನ್ನು ಸದಾ ಧ್ಯಾನಿಸಬೇಕು. ಆಕಾಶದಿಂದ ಬಿದ್ದ ನೀರು ಸಮುದ್ರವನ್ನು ಸೇರುವಂತೆ, ಎಲ್ಲ ದೇವತೆಗಳಿಗೆ ಮಾಡಿದ ನಮಸ್ಕಾರ ಕೇಶವನನ್ನು ಸೇರುತ್ತದೆ.`,
      `జగత్తుకు ఏకైక నేత్రం, సృష్టి స్థితి లయాలకు కారణం, త్రయీమయుడు, త్రిగుణధారి, బ్రహ్మ నారాయణ శంకర స్వరూపుడైన సవితకు నమస్కారం. సూర్యమండల మధ్యంలో పద్మాసనంపై కూర్చున్న, కేయూరాలు, మకరకుండలాలు, కిరీటం, హారం ధరించిన, బంగారు దేహం గల, శంఖచక్రధారి నారాయణుని సదా ధ్యానించాలి. ఆకాశం నుండి పడిన నీరు సముద్రాన్ని చేరినట్లు, సర్వ దేవతలకు చేసిన నమస్కారం కేశవుని చేరుతుంది.`,
      `உலகின் ஒரே கண்ணும், படைப்பு காப்பு அழிவுக்குக் காரணமும், மூன்று வேதங்களின் வடிவும், முக்குணங்களைத் தாங்குபவனும், பிரம்மா நாராயணன் சங்கரன் வடிவுமான ஸவித்ருவுக்கு நமஸ்காரம். சூரிய மண்டலத்தின் நடுவில் தாமரை ஆசனத்தில் அமர்ந்த, தோள்வளை, மகர குண்டலம், கிரீடம், மாலை அணிந்த, பொன்னுடலுடைய, சங்கு சக்கரம் ஏந்திய நாராயணனை எப்போதும் தியானிக்க வேண்டும். வானிலிருந்து விழும் நீர் கடலைச் சேர்வது போல், எல்லாத் தேவர்களுக்கும் செய்யும் நமஸ்காரம் கேசவனைச் சேர்கிறது.`,
      `जगत् के एकमात्र नेत्र, सृष्टि, स्थिति और लय के कारण, त्रयीमय, त्रिगुणधारी, ब्रह्मा नारायण शङ्कर स्वरूप सविता को नमस्कार। सूर्यमण्डल के मध्य कमलासन पर विराजमान, केयूर, मकरकुण्डल, किरीट और हार धारण किए, स्वर्णदेह, शङ्ख-चक्रधारी नारायण का सदा ध्यान करना चाहिए। जैसे आकाश से गिरा जल समुद्र में जाता है, वैसे सब देवों को किया नमस्कार केशव तक पहुँचता है।`) },

  { id:'samarpana', t:`समर्पणम्`, ash:'mental',
    how: L(`Offer the whole rite to the Lord, do ācamana (step 2), and conclude.`,
      `ಸಮಗ್ರ ಕರ್ಮವನ್ನು ಭಗವಂತನಿಗೆ ಅರ್ಪಿಸಿ, ಆಚಮನ (ಹಂತ 2) ಮಾಡಿ ಮುಗಿಸಿ.`,
      `సమస్త కర్మను భగవంతునికి అర్పించి, ఆచమనం (దశ 2) చేసి ముగించండి.`,
      `முழுக் கர்மத்தையும் இறைவனுக்கு அர்ப்பணித்து, ஆசமனம் (படி 2) செய்து நிறைவு செய்யவும்.`,
      `सम्पूर्ण कर्म भगवान् को अर्पित करें, आचमन (चरण 2) करें और समापन करें।`),
    m: [ { d:`कायेन वाचा मनसेन्द्रियैर्वा बुद्ध्यात्मना वा प्रकृतेः स्वभावात् ।
करोमि यद्यत्सकलं परस्मै नारायणायेति समर्पयामि ॥` },
         { d:`अद्या नो देव सवितः प्रजावत्सावीः सौभगम् । परा दुष्ष्वप्नियग्ं सुव ॥
विश्वानि देव सवितर्दुरितानि परा सुव । यद्भद्रं तन्म आ सुव ॥` },
         { d:`ॐ तत्सत् ब्रह्मार्पणमस्तु ॥` } ],
    mean: L(`Whatever I do with body, speech, mind, senses, intellect, or by my nature, I offer it all to the Supreme, Nārāyaṇa. O divine Savitṛ, grant us prosperity with progeny today and drive away bad dreams; drive away all evils and bring us what is good. Om, that is real: may this be an offering to Brahman.`,
      `ದೇಹ, ಮಾತು, ಮನಸ್ಸು, ಇಂದ್ರಿಯಗಳು, ಬುದ್ಧಿ ಅಥವಾ ಸ್ವಭಾವದಿಂದ ನಾನು ಮಾಡುವ ಎಲ್ಲವನ್ನೂ ಪರಮಾತ್ಮನಾದ ನಾರಾಯಣನಿಗೆ ಅರ್ಪಿಸುತ್ತೇನೆ. ಓ ಸವಿತೃ ದೇವ, ಇಂದು ನಮಗೆ ಸಂತಾನಸಹಿತ ಸೌಭಾಗ್ಯ ನೀಡು, ಕೆಟ್ಟ ಕನಸುಗಳನ್ನು ದೂರಮಾಡು; ಎಲ್ಲ ದುರಿತಗಳನ್ನು ದೂರಮಾಡಿ ಒಳ್ಳೆಯದನ್ನು ತಾ. ಓಂ ತತ್ ಸತ್: ಇದು ಬ್ರಹ್ಮಾರ್ಪಣವಾಗಲಿ.`,
      `దేహం, వాక్కు, మనసు, ఇంద్రియాలు, బుద్ధి లేదా స్వభావం వల్ల నేను చేసేదంతా పరమాత్ముడైన నారాయణునికి అర్పిస్తున్నాను. ఓ సవితృ దేవా, ఈరోజు మాకు సంతానసహిత సౌభాగ్యం ఇవ్వు, చెడు కలలను దూరం చేయి; సమస్త దురితాలను దూరం చేసి మంచిని తెమ్ము. ఓం తత్ సత్: ఇది బ్రహ్మార్పణమగుగాక.`,
      `உடல், சொல், மனம், புலன்கள், அறிவு அல்லது இயல்பால் நான் செய்யும் அனைத்தையும் பரம்பொருளான நாராயணனுக்கு அர்ப்பணிக்கிறேன். ஸவித்ரு தேவனே, இன்று எங்களுக்கு மக்கட்செல்வத்துடன் நற்பேறு அருள், தீய கனவுகளை விரட்டு; எல்லாத் தீமைகளையும் விலக்கி நல்லதைக் கொண்டு வா. ஓம் தத் ஸத்: இது பிரம்மார்ப்பணம் ஆகட்டும்.`,
      `शरीर, वाणी, मन, इन्द्रियों, बुद्धि या स्वभाव से मैं जो कुछ करता हूँ, वह सब परमात्मा नारायण को अर्पित करता हूँ। हे सविता देव, आज हमें सन्तान सहित सौभाग्य दो, दुःस्वप्न दूर करो; सब दुरित दूर करके जो भद्र है वह लाओ। ॐ तत्सत्: यह ब्रह्मार्पण हो।`) }
];

/* Āśauca, tīrtha and yajñopavīta guide */
const VD_ASH = {
  title: L(`Āśauca, tīrtha and yajñopavīta`, `ಆಶೌಚ, ತೀರ್ಥ ಮತ್ತು ಯಜ್ಞೋಪವೀತ`, `ఆశౌచం, తీర్థం, యజ్ఞోపవీతం`, `ஆசௌசம், தீர்த்தம், பூணூல்`, `आशौच, तीर्थ और यज्ञोपवीत`),
  sub: L(`Death (sūtaka) and birth (puruḍu): what changes, how to end it, and changing the sacred thread`,
    `ಮರಣ (ಸೂತಕ) ಮತ್ತು ಜನನ (ಪುರುಡು): ಏನು ಬದಲಾಗುತ್ತದೆ, ಹೇಗೆ ಮುಗಿಸುವುದು, ಜನಿವಾರ ಬದಲಾವಣೆ`,
    `మరణం (సూతకం), జననం (పురుడు): ఏమి మారుతుంది, ఎలా ముగించాలి, జంధ్యం మార్పు`,
    `இறப்பு, பிறப்புத் தீட்டு: என்ன மாறும், எப்படி முடிப்பது, பூணூல் மாற்றுவது`,
    `मृत्यु (सूतक) और जन्म (जननाशौच): क्या बदलता है, कैसे समाप्त करें, यज्ञोपवीत बदलना`),
  sections: [
    { id:'kinds',
      h: L(`What āśauca is, and how long it lasts`, `ಆಶೌಚ ಎಂದರೇನು, ಎಷ್ಟು ದಿನ`, `ఆశౌచం అంటే ఏమిటి, ఎన్ని రోజులు`, `ஆசௌசம் என்றால் என்ன, எத்தனை நாள்`, `आशौच क्या है, कितने दिन`),
      p: L(`Āśauca is the period of ritual impurity that follows a birth (jāta-āśauca, puruḍu) or a death (mṛta-āśauca, sūtaka) in the family. The periods most commonly followed are:`,
        `ಕುಟುಂಬದಲ್ಲಿ ಜನನ (ಜಾತಾಶೌಚ, ಪುರುಡು) ಅಥವಾ ಮರಣ (ಮೃತಾಶೌಚ, ಸೂತಕ) ಆದಾಗ ಬರುವ ಅಶುಚಿಯ ಅವಧಿಯೇ ಆಶೌಚ. ಸಾಮಾನ್ಯವಾಗಿ ಪಾಲಿಸುವ ಅವಧಿಗಳು:`,
        `కుటుంబంలో జననం (జాతాశౌచం, పురుడు) లేదా మరణం (మృతాశౌచం, సూతకం) జరిగినప్పుడు వచ్చే అశుచి కాలమే ఆశౌచం. సాధారణంగా పాటించే కాలాలు:`,
        `குடும்பத்தில் பிறப்பு (ஜாதாசௌசம், விருத்தித் தீட்டு) அல்லது இறப்பு (மிருதாசௌசம், தீட்டு) நேர்ந்தபின் வரும் தீட்டுக் காலமே ஆசௌசம். பொதுவாகக் கடைப்பிடிக்கப்படும் காலங்கள்:`,
        `परिवार में जन्म (जननाशौच, वृद्धि) या मृत्यु (मरणाशौच, सूतक) होने पर जो अशुद्धि काल होता है, उसे आशौच कहते हैं। सामान्यतः पालन की जाने वाली अवधियाँ:`),
      list: [
        L(`Death of a sapiṇḍa (a relative within seven generations on the father's side, including parents, brothers, sons and their families): 10 days.`, `ಸಪಿಂಡರ ಮರಣ (ತಂದೆಯ ಕಡೆಯ ಏಳು ತಲೆಮಾರಿನೊಳಗಿನ ಸಂಬಂಧಿಗಳು, ತಂದೆ ತಾಯಿ, ಸಹೋದರರು, ಮಕ್ಕಳು ಸೇರಿ): 10 ದಿನ.`, `సపిండుల మరణం (తండ్రి వైపు ఏడు తరాలలోపు బంధువులు, తల్లిదండ్రులు, సోదరులు, పిల్లలు సహా): 10 రోజులు.`, `ஸபிண்டர் இறப்பு (தந்தை வழியில் ஏழு தலைமுறைக்குள் உள்ள உறவினர், பெற்றோர், சகோதரர், மக்கள் உட்பட): 10 நாள்.`, `सपिण्ड की मृत्यु (पिता की ओर से सात पीढ़ी के भीतर के सम्बन्धी, माता-पिता, भाई, पुत्र सहित): 10 दिन।`),
        L(`Birth in the family: 10 days for the father and the sapiṇḍas. The mother observes a longer period by custom.`, `ಕುಟುಂಬದಲ್ಲಿ ಜನನ: ತಂದೆ ಮತ್ತು ಸಪಿಂಡರಿಗೆ 10 ದಿನ. ತಾಯಿ ಸಂಪ್ರದಾಯದಂತೆ ಹೆಚ್ಚು ಕಾಲ ಪಾಲಿಸುತ್ತಾರೆ.`, `కుటుంబంలో జననం: తండ్రికి, సపిండులకు 10 రోజులు. తల్లి ఆచారం ప్రకారం ఎక్కువ కాలం పాటిస్తారు.`, `குடும்பத்தில் பிறப்பு: தந்தைக்கும் ஸபிண்டர்களுக்கும் 10 நாள். தாய் வழக்கப்படி அதிக காலம் கடைப்பிடிப்பார்.`, `परिवार में जन्म: पिता और सपिण्डों के लिए 10 दिन। माता परम्परा के अनुसार अधिक समय पालन करती हैं।`),
        L(`Death of a more distant agnate (samānodaka, 8th to 14th generation): 3 days.`, `ದೂರದ ಜ್ಞಾತಿಗಳ ಮರಣ (ಸಮಾನೋದಕ, 8 ರಿಂದ 14ನೇ ತಲೆಮಾರು): 3 ದಿನ.`, `దూరపు జ్ఞాతుల మరణం (సమానోదకులు, 8 నుండి 14వ తరం): 3 రోజులు.`, `தூரத்து ஞாதிகளின் இறப்பு (ஸமானோதகர், 8 முதல் 14ஆம் தலைமுறை): 3 நாள்.`, `दूर के सगोत्रों की मृत्यु (समानोदक, 8वीं से 14वीं पीढ़ी): 3 दिन।`),
        L(`If news of a death reaches you within the 10 days, observe only the days that remain. If it reaches you after the 10 days but within a year, observe 3 days. After a year, a bath is enough.`, `ಮರಣದ ಸುದ್ದಿ 10 ದಿನಗಳೊಳಗೆ ತಿಳಿದರೆ ಉಳಿದ ದಿನಗಳನ್ನು ಮಾತ್ರ ಪಾಲಿಸಿ. 10 ದಿನಗಳ ನಂತರ ಆದರೆ ವರ್ಷದೊಳಗೆ ತಿಳಿದರೆ 3 ದಿನ. ವರ್ಷದ ನಂತರ ಸ್ನಾನ ಸಾಕು.`, `మరణ వార్త 10 రోజులలోపు తెలిస్తే మిగిలిన రోజులే పాటించండి. 10 రోజుల తర్వాత కానీ సంవత్సరం లోపు తెలిస్తే 3 రోజులు. సంవత్సరం తర్వాత స్నానం చాలు.`, `இறப்புச் செய்தி 10 நாளுக்குள் தெரிந்தால் மீதமுள்ள நாட்களை மட்டும் கடைப்பிடிக்கவும். 10 நாளுக்குப் பின் ஆனால் ஓராண்டுக்குள் தெரிந்தால் 3 நாள். ஓராண்டுக்குப் பின் நீராடுதல் போதும்.`, `मृत्यु का समाचार 10 दिन के भीतर मिले तो केवल शेष दिन पालन करें। 10 दिन के बाद पर वर्ष के भीतर मिले तो 3 दिन। वर्ष के बाद स्नान पर्याप्त है।`),
        L(`If a second āśauca of the same or shorter length begins during the first, both end together with the first.`, `ಒಂದು ಆಶೌಚದ ಮಧ್ಯೆ ಅಷ್ಟೇ ಅಥವಾ ಕಡಿಮೆ ಅವಧಿಯ ಇನ್ನೊಂದು ಆಶೌಚ ಬಂದರೆ, ಎರಡೂ ಮೊದಲನೆಯದರೊಂದಿಗೇ ಮುಗಿಯುತ್ತವೆ.`, `ఒక ఆశౌచం మధ్యలో అంతే లేదా తక్కువ కాలపు మరొక ఆశౌచం వస్తే, రెండూ మొదటిదానితోనే ముగుస్తాయి.`, `ஒரு ஆசௌசத்தின் நடுவே அதே அளவு அல்லது குறைவான காலத்து இன்னொரு ஆசௌசம் வந்தால், இரண்டும் முதலாவதுடனே முடியும்.`, `एक आशौच के बीच उतनी ही या कम अवधि का दूसरा आशौच आए तो दोनों पहले के साथ ही समाप्त होते हैं।`)
      ],
      note: L(`These are the periods most commonly followed by Smārta brāhmaṇas. Rules for married daughters, maternal relatives, infants and other cases differ, and your purohita's ruling prevails.`,
        `ಇವು ಸ್ಮಾರ್ತ ಬ್ರಾಹ್ಮಣರು ಸಾಮಾನ್ಯವಾಗಿ ಪಾಲಿಸುವ ಅವಧಿಗಳು. ವಿವಾಹಿತ ಹೆಣ್ಣುಮಕ್ಕಳು, ತಾಯಿಯ ಕಡೆಯ ಸಂಬಂಧಿಗಳು, ಶಿಶುಗಳು ಮುಂತಾದ ಸಂದರ್ಭಗಳ ನಿಯಮಗಳು ಬೇರೆ; ನಿಮ್ಮ ಪುರೋಹಿತರ ನಿರ್ಣಯವೇ ಅಂತಿಮ.`,
        `ఇవి స్మార్త బ్రాహ్మణులు సాధారణంగా పాటించే కాలాలు. వివాహిత కుమార్తెలు, తల్లి వైపు బంధువులు, శిశువులు మొదలైన సందర్భాల నియమాలు వేరు; మీ పురోహితుల నిర్ణయమే అంతిమం.`,
        `இவை ஸ்மார்த்த அந்தணர்கள் பொதுவாகக் கடைப்பிடிக்கும் காலங்கள். மணமான பெண்கள், தாய்வழி உறவினர், குழந்தைகள் போன்றவற்றுக்கு விதிகள் வேறுபடும்; உங்கள் புரோகிதரின் முடிவே இறுதி.`,
        `ये स्मार्त ब्राह्मणों द्वारा सामान्यतः पालन की जाने वाली अवधियाँ हैं। विवाहित पुत्रियों, मातृपक्ष के सम्बन्धियों, शिशुओं आदि के नियम भिन्न हैं; आपके पुरोहित का निर्णय ही मान्य है।`) },

    { id:'during',
      h: L(`During āśauca`, `ಆಶೌಚದ ಅವಧಿಯಲ್ಲಿ`, `ఆశౌచ కాలంలో`, `ஆசௌச காலத்தில்`, `आशौच के दौरान`),
      list: [
        L(`Continue Sandhyāvandana in the shortened form (choose Āśauca in the vidhāna above): prāṇāyāma without mantras, the other mantras in the mind, the Gāyatrī recited for arghya, and at least 10 Gāyatrī japa mentally.`, `ಸಂಧ್ಯಾವಂದನೆಯನ್ನು ಸಂಕ್ಷಿಪ್ತ ರೂಪದಲ್ಲಿ ಮುಂದುವರಿಸಿ (ಮೇಲಿನ ವಿಧಾನದಲ್ಲಿ "ಆಶೌಚ" ಆಯ್ಕೆಮಾಡಿ): ಮಂತ್ರವಿಲ್ಲದ ಪ್ರಾಣಾಯಾಮ, ಉಳಿದ ಮಂತ್ರಗಳು ಮನಸ್ಸಿನಲ್ಲಿ, ಅರ್ಘ್ಯಕ್ಕೆ ಗಾಯತ್ರೀ ಉಚ್ಚಾರಣೆ, ಕನಿಷ್ಠ 10 ಗಾಯತ್ರೀ ಜಪ ಮನಸ್ಸಿನಲ್ಲಿ.`, `సంధ్యావందనాన్ని సంక్షిప్త రూపంలో కొనసాగించండి (పైని విధానంలో "ఆశౌచం" ఎంచుకోండి): మంత్రం లేని ప్రాణాయామం, మిగిలిన మంత్రాలు మనసులో, అర్ఘ్యానికి గాయత్రీ ఉచ్చారణ, కనీసం 10 గాయత్రీ జపం మనసులో.`, `சந்தியாவந்தனத்தைச் சுருக்கமாகத் தொடரவும் (மேலே உள்ள முறையில் "ஆசௌசம்" தேர்வு செய்யவும்): மந்திரமில்லாத பிராணாயாமம், மற்ற மந்திரங்கள் மனதிற்குள், அர்க்கியத்துக்குக் காயத்ரி உச்சரிப்பு, குறைந்தது 10 காயத்ரி ஜபம் மனதிற்குள்.`, `सन्ध्यावन्दन संक्षिप्त रूप में जारी रखें (ऊपर की विधि में "आशौच" चुनें): बिना मन्त्र प्राणायाम, शेष मन्त्र मन में, अर्घ्य के लिए गायत्री उच्चारण, और कम से कम 10 गायत्री जप मन में।`),
        L(`Do not perform deva-pūjā at home (someone not under āśauca may do it), and do not visit temples.`, `ಮನೆಯಲ್ಲಿ ದೇವಪೂಜೆ ಮಾಡಬೇಡಿ (ಆಶೌಚವಿಲ್ಲದ ಬೇರೊಬ್ಬರು ಮಾಡಬಹುದು), ದೇವಾಲಯಗಳಿಗೆ ಹೋಗಬೇಡಿ.`, `ఇంట్లో దేవపూజ చేయకండి (ఆశౌచం లేని మరొకరు చేయవచ్చు), దేవాలయాలకు వెళ్ళకండి.`, `வீட்டில் தேவபூஜை செய்ய வேண்டாம் (தீட்டு இல்லாத வேறொருவர் செய்யலாம்), கோயில்களுக்குச் செல்ல வேண்டாம்.`, `घर में देवपूजा न करें (आशौच रहित कोई अन्य व्यक्ति कर सकता है), और मन्दिर न जाएँ।`),
        L(`Brahmayajña, Vaiśvadeva and Vedic study are suspended. Do not perform or attend auspicious ceremonies.`, `ಬ್ರಹ್ಮಯಜ್ಞ, ವೈಶ್ವದೇವ, ವೇದಾಧ್ಯಯನ ನಿಲ್ಲುತ್ತವೆ. ಶುಭಕಾರ್ಯಗಳನ್ನು ಮಾಡಬೇಡಿ, ಅವುಗಳಿಗೆ ಹೋಗಬೇಡಿ.`, `బ్రహ్మయజ్ఞం, వైశ్వదేవం, వేదాధ్యయనం ఆగిపోతాయి. శుభకార్యాలు చేయకండి, వాటికి వెళ్ళకండి.`, `பிரம்மயஞ்ஞம், வைஸ்வதேவம், வேத அத்யயனம் நிறுத்தப்படும். சுபகாரியங்களைச் செய்யவோ அவற்றுக்குச் செல்லவோ வேண்டாம்.`, `ब्रह्मयज्ञ, वैश्वदेव और वेदाध्ययन स्थगित रहते हैं। शुभ कार्य न करें और उनमें सम्मिलित न हों।`),
        L(`Do not offer namaskāra or abhivādana to others, and avoid touching people outside the family.`, `ಇತರರಿಗೆ ನಮಸ್ಕಾರ ಅಥವಾ ಅಭಿವಾದನ ಮಾಡಬೇಡಿ, ಕುಟುಂಬದ ಹೊರಗಿನವರನ್ನು ಮುಟ್ಟಬೇಡಿ.`, `ఇతరులకు నమస్కారం లేదా అభివాదనం చేయకండి, కుటుంబం బయటివారిని తాకకండి.`, `பிறருக்கு நமஸ்காரமோ அபிவாதனமோ செய்ய வேண்டாம், குடும்பத்துக்கு வெளியே உள்ளவர்களைத் தொட வேண்டாம்.`, `दूसरों को नमस्कार या अभिवादन न करें, और परिवार के बाहर के लोगों को न छुएँ।`),
        L(`Keep the same yajñopavīta until the āśauca ends, unless your purohita asks you to change it during the funeral rites.`, `ಆಶೌಚ ಮುಗಿಯುವವರೆಗೆ ಅದೇ ಜನಿವಾರ ಧರಿಸಿ; ಅಪರ ಕರ್ಮಗಳ ಸಮಯದಲ್ಲಿ ಪುರೋಹಿತರು ಬದಲಿಸಲು ಹೇಳಿದರೆ ಮಾತ್ರ ಬದಲಿಸಿ.`, `ఆశౌచం ముగిసే వరకు అదే జంధ్యం ధరించండి; అపరకర్మల సమయంలో పురోహితులు మార్చమంటేనే మార్చండి.`, `ஆசௌசம் முடியும் வரை அதே பூணூலை அணியவும்; அபரக் கிரியைகளின்போது புரோகிதர் மாற்றச் சொன்னால் மட்டும் மாற்றவும்.`, `आशौच समाप्त होने तक वही यज्ञोपवीत पहनें; अन्त्येष्टि कर्मों में पुरोहित बदलने को कहें तभी बदलें।`)
      ] },

    { id:'end',
      h: L(`Ending āśauca (the 11th day)`, `ಆಶೌಚ ಸಮಾಪ್ತಿ (11ನೇ ದಿನ)`, `ఆశౌచ సమాప్తి (11వ రోజు)`, `ஆசௌச நிவர்த்தி (11ஆம் நாள்)`, `आशौच समाप्ति (11वाँ दिन)`),
      list: [
        L(`Bathe with your clothes on (sacela snāna), including the head. Where your family follows it, have the head shaved before the bath.`, `ಬಟ್ಟೆ ಸಹಿತ ತಲೆಸ್ನಾನ (ಸಚೇಲ ಸ್ನಾನ) ಮಾಡಿ. ಮನೆತನದ ಆಚರಣೆಯಿದ್ದರೆ ಸ್ನಾನಕ್ಕೆ ಮೊದಲು ಕ್ಷೌರ ಮಾಡಿಸಿ.`, `బట్టలతో సహా తలస్నానం (సచేల స్నానం) చేయండి. కుటుంబ ఆచారమైతే స్నానానికి ముందు క్షౌరం చేయించుకోండి.`, `ஆடையுடன் தலைக்குக் குளிக்கவும் (சசேல ஸ்நானம்). குடும்ப வழக்கம் இருந்தால் குளிக்கும் முன் க்ஷௌரம் செய்துகொள்ளவும்.`, `वस्त्रों सहित सिर से स्नान (सचैल स्नान) करें। पारिवारिक परम्परा हो तो स्नान से पहले क्षौर कराएँ।`),
        L(`Wear fresh clothes and apply bhasma or tilaka.`, `ಶುಭ್ರ ಬಟ್ಟೆ ಧರಿಸಿ, ಭಸ್ಮ ಅಥವಾ ತಿಲಕ ಧರಿಸಿ.`, `శుభ్రమైన బట్టలు ధరించి, భస్మం లేదా తిలకం ధరించండి.`, `தூய ஆடை அணிந்து, விபூதி அல்லது திலகம் இட்டுக்கொள்ளவும்.`, `स्वच्छ वस्त्र पहनें और भस्म या तिलक लगाएँ।`),
        L(`Have the purohita perform puṇyāhavācana, or the śuddhi rite your family follows, and take pañcagavya with the mantra below.`, `ಪುರೋಹಿತರಿಂದ ಪುಣ್ಯಾಹವಾಚನ ಅಥವಾ ನಿಮ್ಮ ಮನೆತನದ ಶುದ್ಧಿ ಕರ್ಮ ಮಾಡಿಸಿ, ಕೆಳಗಿನ ಮಂತ್ರದೊಂದಿಗೆ ಪಂಚಗವ್ಯ ಪ್ರಾಶನ ಮಾಡಿ.`, `పురోహితులచే పుణ్యాహవాచనం లేదా మీ కుటుంబ శుద్ధి కర్మ చేయించి, క్రింది మంత్రంతో పంచగవ్య ప్రాశనం చేయండి.`, `புரோகிதரைக் கொண்டு புண்யாஹவாசனம் அல்லது உங்கள் குடும்பச் சுத்தி கர்மம் செய்து, கீழே உள்ள மந்திரத்துடன் பஞ்சகவ்யம் உட்கொள்ளவும்.`, `पुरोहित से पुण्याहवाचन या अपने परिवार की शुद्धि विधि कराएँ, और नीचे के मन्त्र से पञ्चगव्य प्राशन करें।`),
        L(`Change the yajñopavīta (see the vidhi below).`, `ಜನಿವಾರ ಬದಲಿಸಿ (ಕೆಳಗಿನ ವಿಧಿ ನೋಡಿ).`, `జంధ్యం మార్చండి (క్రింది విధి చూడండి).`, `பூணூல் மாற்றவும் (கீழே உள்ள முறையைப் பார்க்கவும்).`, `यज्ञोपवीत बदलें (नीचे की विधि देखें)।`),
        L(`Take tīrtha with the mantra below.`, `ಕೆಳಗಿನ ಮಂತ್ರದೊಂದಿಗೆ ತೀರ್ಥ ಸ್ವೀಕರಿಸಿ.`, `క్రింది మంత్రంతో తీర్థం స్వీకరించండి.`, `கீழே உள்ள மந்திரத்துடன் தீர்த்தம் உட்கொள்ளவும்.`, `नीचे के मन्त्र से तीर्थ ग्रहण करें।`),
        L(`Perform the full Sandhyāvandana with at least 108 Gāyatrī japa, and resume daily worship.`, `ಕನಿಷ್ಠ 108 ಗಾಯತ್ರೀ ಜಪದೊಂದಿಗೆ ಪೂರ್ಣ ಸಂಧ್ಯಾವಂದನೆ ಮಾಡಿ, ನಿತ್ಯ ಪೂಜೆಯನ್ನು ಮತ್ತೆ ಆರಂಭಿಸಿ.`, `కనీసం 108 గాయత్రీ జపంతో పూర్తి సంధ్యావందనం చేసి, నిత్యపూజను మళ్ళీ ప్రారంభించండి.`, `குறைந்தது 108 காயத்ரி ஜபத்துடன் முழு சந்தியாவந்தனம் செய்து, நித்ய பூஜையை மீண்டும் தொடங்கவும்.`, `कम से कम 108 गायत्री जप सहित पूर्ण सन्ध्यावन्दन करें और नित्य पूजा पुनः आरम्भ करें।`)
      ],
      note: L(`For a 3-day āśauca, do the same on the 4th day.`, `3 ದಿನಗಳ ಆಶೌಚಕ್ಕೆ ಇದನ್ನೇ 4ನೇ ದಿನ ಮಾಡಿ.`, `3 రోజుల ఆశౌచానికి ఇదే 4వ రోజు చేయండి.`, `3 நாள் ஆசௌசத்துக்கு இதையே 4ஆம் நாள் செய்யவும்.`, `3 दिन के आशौच में यही चौथे दिन करें।`),
      m: [ { label: L(`Pañcagavya prāśana`, `ಪಂಚಗವ್ಯ ಪ್ರಾಶನ`, `పంచగవ్య ప్రాశనం`, `பஞ்சகவ்ய ப்ராசனம்`, `पञ्चगव्य प्राशन`),
             d:`यत्त्वगस्थिगतं पापं देहे तिष्ठति मामके ।
प्राशनात्पञ्चगव्यस्य दहत्वग्निरिवेन्धनम् ॥`,
             mean: L(`May the sin lodged in the skin and bones of my body be burnt by taking pañcagavya, as fire burns fuel.`, `ನನ್ನ ದೇಹದ ಚರ್ಮ, ಅಸ್ಥಿಗಳಲ್ಲಿರುವ ಪಾಪವನ್ನು, ಬೆಂಕಿ ಸೌದೆಯನ್ನು ಸುಡುವಂತೆ, ಪಂಚಗವ್ಯ ಪ್ರಾಶನ ಸುಟ್ಟುಹಾಕಲಿ.`, `నా దేహంలోని చర్మం, ఎముకలలో ఉన్న పాపాన్ని, అగ్ని కట్టెలను కాల్చినట్లు, పంచగవ్య ప్రాశనం కాల్చివేయుగాక.`, `என் உடலின் தோலிலும் எலும்பிலும் உள்ள பாவத்தை, நெருப்பு விறகை எரிப்பது போல், பஞ்சகவ்யம் உட்கொள்வது எரிக்கட்டும்.`, `मेरे शरीर की त्वचा और अस्थियों में स्थित पाप को, जैसे अग्नि ईंधन को जलाती है, वैसे पञ्चगव्य का प्राशन जला दे।`) } ] },

    { id:'tirtha',
      h: L(`Taking tīrtha`, `ತೀರ್ಥ ಸ್ವೀಕಾರ`, `తీర్థ స్వీకారం`, `தீர்த்தம் உட்கொள்ளுதல்`, `तीर्थ ग्रहण`),
      p: L(`Hold the right palm cupped over the left. Receive a few drops of tīrtha and sip it with the mantra, without the hand touching the lips. Some take it three times. Touch the remaining moisture to the eyes and head, and do not let it fall on the ground.`,
        `ಬಲ ಅಂಗೈಯನ್ನು ಎಡ ಅಂಗೈ ಮೇಲೆ ಬೊಗಸೆಯಾಗಿ ಹಿಡಿಯಿರಿ. ಕೆಲವು ಹನಿ ತೀರ್ಥ ಪಡೆದು, ಕೈ ತುಟಿಗೆ ತಾಗದಂತೆ ಮಂತ್ರದೊಂದಿಗೆ ಸೇವಿಸಿ. ಕೆಲವರು ಮೂರು ಬಾರಿ ಸ್ವೀಕರಿಸುತ್ತಾರೆ. ಉಳಿದ ತೇವವನ್ನು ಕಣ್ಣು ಮತ್ತು ತಲೆಗೆ ಒತ್ತಿಕೊಳ್ಳಿ, ನೆಲಕ್ಕೆ ಬೀಳಿಸಬೇಡಿ.`,
        `కుడి అరచేతిని ఎడమ అరచేతిపై దోసిలిగా పట్టుకోండి. కొన్ని చుక్కల తీర్థం తీసుకొని, చేయి పెదవులకు తగలకుండా మంత్రంతో సేవించండి. కొందరు మూడుసార్లు తీసుకుంటారు. మిగిలిన తడిని కళ్ళకు, తలకు అద్దుకోండి, నేలపై పడనీయకండి.`,
        `வலது உள்ளங்கையை இடது உள்ளங்கை மேல் குழிவாக வைக்கவும். சில துளி தீர்த்தம் பெற்று, கை உதட்டில் படாமல் மந்திரத்துடன் பருகவும். சிலர் மூன்று முறை பெறுவர். மீதமுள்ள ஈரத்தைக் கண்களிலும் தலையிலும் ஒற்றிக்கொள்ளவும், தரையில் விழ விட வேண்டாம்.`,
        `दाहिनी हथेली को बाईं हथेली पर अञ्जलि के रूप में रखें। कुछ बूँद तीर्थ लेकर, हाथ होंठों से न छुए ऐसे मन्त्र सहित पान करें। कुछ लोग तीन बार लेते हैं। शेष नमी आँखों और सिर पर लगाएँ, और भूमि पर न गिराएँ।`),
      m: [ { d:`अकालमृत्युहरणं सर्वव्याधिनिवारणम् ।
समस्तपापक्षयकरं विष्णुपादोदकं शुभम् ॥`,
             mean: L(`The auspicious water from the Lord's feet, which removes untimely death, cures all illness and destroys all sins.`, `ಅಕಾಲ ಮೃತ್ಯುವನ್ನು ಹರಿಸುವ, ಎಲ್ಲ ರೋಗಗಳನ್ನು ನಿವಾರಿಸುವ, ಸಮಸ್ತ ಪಾಪಗಳನ್ನು ನಾಶಮಾಡುವ ಶುಭಕರವಾದ ವಿಷ್ಣುಪಾದೋದಕ.`, `అకాల మృత్యువును హరించే, సర్వ వ్యాధులను నివారించే, సమస్త పాపాలను నశింపజేసే శుభకరమైన విష్ణుపాదోదకం.`, `அகால மரணத்தைப் போக்கும், எல்லா நோய்களையும் நீக்கும், எல்லாப் பாவங்களையும் அழிக்கும் மங்களமான விஷ்ணு பாதோதகம்.`, `अकाल मृत्यु को हरने वाला, सब रोगों का निवारण करने वाला, समस्त पापों का नाश करने वाला शुभ विष्णुपादोदक।`) } ],
      note: L(`At a Śiva temple, the last line is said as "śivapādodakaṃ śubham".`, `ಶಿವ ದೇವಾಲಯದಲ್ಲಿ ಕೊನೆಯ ಪಾದವನ್ನು "ಶಿವಪಾದೋದಕಂ ಶುಭಂ" ಎಂದು ಹೇಳುತ್ತಾರೆ.`, `శివాలయంలో చివరి పాదాన్ని "శివపాదోదకం శుభం" అని చెబుతారు.`, `சிவன் கோயிலில் கடைசி அடியை "சிவபாதோதகம் சுபம்" என்று சொல்வர்.`, `शिव मन्दिर में अन्तिम चरण "शिवपादोदकं शुभम्" बोला जाता है।`) },

    { id:'janivara',
      h: L(`Yajñopavīta dhāraṇa (changing the sacred thread)`, `ಯಜ್ಞೋಪವೀತ ಧಾರಣೆ (ಜನಿವಾರ ಬದಲಾವಣೆ)`, `యజ్ఞోపవీత ధారణ (జంధ్యం మార్పు)`, `யஞ்ஞோபவீத தாரணம் (பூணூல் மாற்றுதல்)`, `यज्ञोपवीत धारण (जनेऊ बदलना)`),
      steps: [
        { p: L(`Bathe and sit facing east. Do ācamana and prāṇāyāma, and say the saṅkalpa.`, `ಸ್ನಾನ ಮಾಡಿ ಪೂರ್ವಾಭಿಮುಖವಾಗಿ ಕುಳಿತುಕೊಳ್ಳಿ. ಆಚಮನ, ಪ್ರಾಣಾಯಾಮ ಮಾಡಿ ಸಂಕಲ್ಪ ಹೇಳಿ.`, `స్నానం చేసి తూర్పు ముఖంగా కూర్చోండి. ఆచమనం, ప్రాణాయామం చేసి సంకల్పం చెప్పండి.`, `நீராடிக் கிழக்கு நோக்கி அமரவும். ஆசமனம், பிராணாயாமம் செய்து சங்கல்பம் சொல்லவும்.`, `स्नान करके पूर्वाभिमुख बैठें। आचमन, प्राणायाम करके सङ्कल्प बोलें।`),
          d: SK + `श्रौतस्मार्तविहित सदाचार नित्यकर्मानुष्ठान योग्यता सिद्ध्यर्थं ब्रह्मतेजोऽभिवृद्ध्यर्थं नूतन यज्ञोपवीत धारणं करिष्ये ॥` },
        { p: L(`Sprinkle the new yajñopavīta with water and hold it while reciting the Gāyatrī 10 times.`, `ಹೊಸ ಜನಿವಾರದ ಮೇಲೆ ನೀರು ಪ್ರೋಕ್ಷಿಸಿ, ಅದನ್ನು ಹಿಡಿದು 10 ಬಾರಿ ಗಾಯತ್ರೀ ಜಪಿಸಿ.`, `కొత్త జంధ్యంపై నీరు ప్రోక్షించి, దానిని పట్టుకొని 10 సార్లు గాయత్రి జపించండి.`, `புதிய பூணூலில் நீர் தெளித்து, அதைப் பிடித்தபடி 10 முறை காயத்ரி ஜபிக்கவும்.`, `नए यज्ञोपवीत पर जल छिड़कें और उसे पकड़कर 10 बार गायत्री जप करें।`) },
        { p: L(`Say the viniyoga. Hold the knot (brahma-granthi) in the right hand at the chest, with the thread stretched down by the left hand. Recite the mantra, pass the thread over the head and bring the right arm out, so that it rests on the left shoulder and hangs at the right hip. Do ācamana.`, `ವಿನಿಯೋಗ ಹೇಳಿ. ಬ್ರಹ್ಮಗ್ರಂಥಿಯನ್ನು ಬಲಗೈಯಲ್ಲಿ ಎದೆಯ ಬಳಿ ಹಿಡಿದು, ಎಡಗೈಯಿಂದ ದಾರವನ್ನು ಕೆಳಗೆ ಹಿಡಿಯಿರಿ. ಮಂತ್ರ ಹೇಳಿ, ತಲೆಯ ಮೇಲಿಂದ ಹಾಕಿಕೊಂಡು ಬಲಗೈ ಹೊರತೆಗೆಯಿರಿ; ಅದು ಎಡ ಹೆಗಲಿನ ಮೇಲೆ ಇದ್ದು ಬಲ ಸೊಂಟದವರೆಗೆ ಇಳಿಯಲಿ. ಆಚಮನ ಮಾಡಿ.`, `వినియోగం చెప్పండి. బ్రహ్మగ్రంథిని కుడి చేతిలో ఛాతీ దగ్గర పట్టుకొని, ఎడమ చేతితో దారాన్ని క్రిందికి పట్టండి. మంత్రం చెప్పి, తల మీదుగా వేసుకొని కుడి చేయి బయటకు తీయండి; అది ఎడమ భుజంపై ఉండి కుడి నడుము వరకు వేలాడాలి. ఆచమనం చేయండి.`, `வினியோகம் சொல்லவும். பிரம்மக்ரந்தியை வலது கையில் மார்பருகே பிடித்து, இடது கையால் நூலைக் கீழே பிடிக்கவும். மந்திரம் சொல்லி, தலை வழியாக அணிந்து வலது கையை வெளியே எடுக்கவும்; அது இடது தோளில் இருந்து வலது இடுப்பு வரை தொங்கட்டும். ஆசமனம் செய்யவும்.`, `विनियोग बोलें। ब्रह्मग्रन्थि को दाहिने हाथ में छाती के पास पकड़ें और बाएँ हाथ से धागा नीचे की ओर तानें। मन्त्र बोलकर सिर के ऊपर से पहनें और दाहिना हाथ बाहर निकालें, जिससे वह बाएँ कंधे पर रहे और दाहिनी कमर तक लटके। आचमन करें।`),
          d:`यज्ञोपवीतधारण महामन्त्रस्य परब्रह्म ऋषिः । त्रिष्टुप् छन्दः । परमात्मा देवता । यज्ञोपवीतधारणे विनियोगः ॥
यज्ञोपवीतं परमं पवित्रं प्रजापतेर्यत्सहजं पुरस्तात् ।
आयुष्यमग्र्यं प्रतिमुञ्च शुभ्रं यज्ञोपवीतं बलमस्तु तेजः ॥`,
          mean: L(`This sacred thread is supremely pure, born with Prajāpati in the beginning. It gives long life and excellence; wear this bright thread, and may it bring strength and radiance.`, `ಈ ಯಜ್ಞೋಪವೀತ ಪರಮ ಪವಿತ್ರ, ಆದಿಯಲ್ಲಿ ಪ್ರಜಾಪತಿಯೊಂದಿಗೆ ಹುಟ್ಟಿದ್ದು. ಆಯುಸ್ಸು ಮತ್ತು ಶ್ರೇಷ್ಠತೆಯನ್ನು ನೀಡುವ ಈ ಶುಭ್ರ ಯಜ್ಞೋಪವೀತವನ್ನು ಧರಿಸು; ಇದು ಬಲ ಮತ್ತು ತೇಜಸ್ಸಾಗಲಿ.`, `ఈ యజ్ఞోపవీతం పరమ పవిత్రం, ఆదిలో ప్రజాపతితో పుట్టినది. ఆయుష్షు, శ్రేష్ఠత ఇచ్చే ఈ శుభ్రమైన యజ్ఞోపవీతాన్ని ధరించు; ఇది బలం, తేజస్సు అగుగాక.`, `இந்த யஞ்ஞோபவீதம் மிகப் புனிதமானது, ஆதியில் பிரஜாபதியுடன் தோன்றியது. ஆயுளும் மேன்மையும் தரும் இந்த வெண்மையான பூணூலை அணிவாயாக; இது பலமும் தேஜஸும் ஆகட்டும்.`, `यह यज्ञोपवीत परम पवित्र है, आदि में प्रजापति के साथ उत्पन्न हुआ। आयु और श्रेष्ठता देने वाले इस शुभ्र यज्ञोपवीत को धारण करो; यह बल और तेज हो।`) },
        { p: L(`A married man (gṛhastha) wears a second set: repeat the mantra and ācamana for it. Some families add a third in place of the upper cloth.`, `ಗೃಹಸ್ಥರು ಎರಡನೇ ಜನಿವಾರ ಧರಿಸುತ್ತಾರೆ: ಅದಕ್ಕೂ ಮಂತ್ರ ಮತ್ತು ಆಚಮನ ಪುನರಾವರ್ತಿಸಿ. ಕೆಲವು ಮನೆತನಗಳು ಉತ್ತರೀಯದ ಬದಲಿಗೆ ಮೂರನೆಯದನ್ನು ಧರಿಸುತ್ತಾರೆ.`, `గృహస్థులు రెండవ జంధ్యం ధరిస్తారు: దానికీ మంత్రం, ఆచమనం మళ్ళీ చేయండి. కొన్ని కుటుంబాలు ఉత్తరీయానికి బదులుగా మూడవది ధరిస్తారు.`, `கிருஹஸ்தர் இரண்டாவது பூணூலை அணிவர்: அதற்கும் மந்திரமும் ஆசமனமும் மீண்டும் செய்யவும். சில குடும்பங்கள் உத்தரீயத்துக்குப் பதிலாக மூன்றாவதை அணிவர்.`, `गृहस्थ दूसरा यज्ञोपवीत भी पहनते हैं: उसके लिए मन्त्र और आचमन दोहराएँ। कुछ परिवार उत्तरीय के स्थान पर तीसरा पहनते हैं।`) },
        { p: L(`Remove the old thread with the mantra below: slip it off downwards over the body, never over the head, and place it in flowing water, at the foot of a tree or in a tulasī pot. Do ācamana. Some books read "visṛjāmi jale brahman".`, `ಕೆಳಗಿನ ಮಂತ್ರದೊಂದಿಗೆ ಹಳೆಯ ಜನಿವಾರ ತೆಗೆಯಿರಿ: ತಲೆಯ ಮೇಲಿಂದ ಅಲ್ಲ, ದೇಹದ ಮೂಲಕ ಕೆಳಕ್ಕೆ ಜಾರಿಸಿ, ಹರಿಯುವ ನೀರಿನಲ್ಲಿ, ಮರದ ಬುಡದಲ್ಲಿ ಅಥವಾ ತುಳಸಿ ಕುಂಡದಲ್ಲಿ ಇಡಿ. ಆಚಮನ ಮಾಡಿ. ಕೆಲವು ಪುಸ್ತಕಗಳಲ್ಲಿ "ವಿಸೃಜಾಮಿ ಜಲೇ ಬ್ರಹ್ಮನ್" ಎಂದಿದೆ.`, `క్రింది మంత్రంతో పాత జంధ్యం తీయండి: తల మీదుగా కాకుండా, దేహం మీదుగా క్రిందికి జార్చి, ప్రవహించే నీటిలో, చెట్టు మొదట్లో లేదా తులసి కోటలో ఉంచండి. ఆచమనం చేయండి. కొన్ని పుస్తకాలలో "విసృజామి జలే బ్రహ్మన్" అని ఉంటుంది.`, `கீழே உள்ள மந்திரத்துடன் பழைய பூணூலை நீக்கவும்: தலை வழியாக அல்ல, உடல் வழியாகக் கீழே நழுவவிட்டு, ஓடும் நீரிலோ மரத்தடியிலோ துளசி மாடத்திலோ வைக்கவும். ஆசமனம் செய்யவும். சில புத்தகங்களில் "விஸ்ருஜாமி ஜலே ப்ரஹ்மன்" என்று உள்ளது.`, `नीचे के मन्त्र से पुराना यज्ञोपवीत उतारें: सिर के ऊपर से नहीं, शरीर से नीचे की ओर सरकाकर उतारें, और बहते जल में, वृक्ष की जड़ में या तुलसी के गमले में रखें। आचमन करें। कुछ पुस्तकों में "विसृजामि जले ब्रह्मन्" पाठ है।`),
          d:`उपवीतं भिन्नतन्तुं जीर्णं कश्मलदूषितम् ।
विसृजामि पुनर्ब्रह्मन् वर्चो दीर्घायुरस्तु मे ॥`,
          mean: L(`I give up this old thread, its strands broken, worn and soiled. O Brahman, may I have radiance and long life.`, `ತಂತುಗಳು ಕಡಿದ, ಹಳೆಯದಾದ, ಮಲಿನವಾದ ಈ ಉಪವೀತವನ್ನು ವಿಸರ್ಜಿಸುತ್ತೇನೆ. ಓ ಬ್ರಹ್ಮನ್, ನನಗೆ ವರ್ಚಸ್ಸು ಮತ್ತು ದೀರ್ಘಾಯುಸ್ಸು ಸಿಗಲಿ.`, `తంతువులు తెగిన, పాతబడిన, మలినమైన ఈ ఉపవీతాన్ని విసర్జిస్తున్నాను. ఓ బ్రహ్మన్, నాకు వర్చస్సు, దీర్ఘాయుష్షు కలుగుగాక.`, `இழைகள் அறுந்த, பழையதான, மாசடைந்த இந்த உபவீதத்தை விடுகிறேன். பிரம்மனே, எனக்குத் தேஜஸும் நீண்ட ஆயுளும் உண்டாகட்டும்.`, `टूटे तन्तुओं वाले, पुराने, मलिन इस उपवीत का मैं विसर्जन करता हूँ। हे ब्रह्मन्, मुझे वर्चस् और दीर्घायु प्राप्त हो।`) },
        { p: L(`Do Gāyatrī japa 10 times (many do 108) and conclude with "Om tat sat brahmārpaṇam astu".`, `10 ಬಾರಿ (ಹಲವರು 108 ಬಾರಿ) ಗಾಯತ್ರೀ ಜಪ ಮಾಡಿ "ಓಂ ತತ್ಸತ್ ಬ್ರಹ್ಮಾರ್ಪಣಮಸ್ತು" ಎಂದು ಮುಗಿಸಿ.`, `10 సార్లు (చాలామంది 108 సార్లు) గాయత్రీ జపం చేసి "ఓం తత్సత్ బ్రహ్మార్పణమస్తు" అని ముగించండి.`, `10 முறை (பலர் 108 முறை) காயத்ரி ஜபம் செய்து "ஓம் தத்ஸத் ப்ரஹ்மார்ப்பணமஸ்து" என்று நிறைவு செய்யவும்.`, `10 बार (बहुत लोग 108 बार) गायत्री जप करें और "ॐ तत्सत् ब्रह्मार्पणमस्तु" से समापन करें।`) }
      ] },

    { id:'when',
      h: L(`When to change the yajñopavīta`, `ಜನಿವಾರ ಯಾವಾಗ ಬದಲಿಸಬೇಕು`, `జంధ్యం ఎప్పుడు మార్చాలి`, `பூணூலை எப்போது மாற்ற வேண்டும்`, `यज्ञोपवीत कब बदलें`),
      list: [
        L(`Every year at Upākarma (Śrāvaṇa pūrṇimā).`, `ಪ್ರತಿ ವರ್ಷ ಉಪಾಕರ್ಮದಂದು (ಶ್ರಾವಣ ಹುಣ್ಣಿಮೆ).`, `ప్రతి సంవత్సరం ఉపాకర్మ రోజు (శ్రావణ పౌర్ణమి).`, `ஒவ்வோர் ஆண்டும் உபாகர்மாவில் (ஆவணி அவிட்டம்).`, `प्रति वर्ष उपाकर्म (श्रावण पूर्णिमा) पर।`),
        L(`At the end of āśauca from a birth or a death.`, `ಜನನ ಅಥವಾ ಮರಣದ ಆಶೌಚ ಮುಗಿದಾಗ.`, `జనన లేదా మరణ ఆశౌచం ముగిసినప్పుడు.`, `பிறப்பு அல்லது இறப்புத் தீட்டு முடிந்ததும்.`, `जन्म या मृत्यु का आशौच समाप्त होने पर।`),
        L(`After a solar or lunar eclipse.`, `ಸೂರ್ಯ ಅಥವಾ ಚಂದ್ರ ಗ್ರಹಣದ ನಂತರ.`, `సూర్య లేదా చంద్ర గ్రహణం తర్వాత.`, `சூரிய அல்லது சந்திர கிரகணத்துக்குப் பின்.`, `सूर्य या चन्द्र ग्रहण के बाद।`),
        L(`Before performing śrāddha, in many families.`, `ಹಲವು ಮನೆತನಗಳಲ್ಲಿ ಶ್ರಾದ್ಧ ಮಾಡುವ ಮೊದಲು.`, `చాలా కుటుంబాలలో శ్రాద్ధం చేసే ముందు.`, `பல குடும்பங்களில் சிராத்தம் செய்யும் முன்.`, `बहुत से परिवारों में श्राद्ध करने से पहले।`),
        L(`After touching a dead body, attending a cremation, or touching a person under āśauca; bathe with your clothes on first.`, `ಶವವನ್ನು ಮುಟ್ಟಿದ, ಶ್ಮಶಾನಕ್ಕೆ ಹೋದ, ಅಥವಾ ಆಶೌಚದಲ್ಲಿರುವವರನ್ನು ಮುಟ್ಟಿದ ನಂತರ; ಮೊದಲು ಬಟ್ಟೆ ಸಹಿತ ಸ್ನಾನ ಮಾಡಿ.`, `శవాన్ని తాకిన, శ్మశానానికి వెళ్ళిన, లేదా ఆశౌచంలో ఉన్నవారిని తాకిన తర్వాత; ముందుగా బట్టలతో స్నానం చేయండి.`, `சடலத்தைத் தொட்ட, மயானத்துக்குச் சென்ற, அல்லது தீட்டில் உள்ளவரைத் தொட்ட பின்; முதலில் ஆடையுடன் நீராடவும்.`, `शव को छूने, श्मशान जाने, या आशौच वाले व्यक्ति को छूने के बाद; पहले वस्त्र सहित स्नान करें।`),
        L(`When it breaks, falls off, or slips off the left shoulder below the left hand.`, `ಅದು ಕಡಿದರೆ, ಬಿದ್ದರೆ, ಅಥವಾ ಎಡ ಹೆಗಲಿನಿಂದ ಎಡಗೈ ಕೆಳಗೆ ಜಾರಿದರೆ.`, `అది తెగితే, పడిపోతే, లేదా ఎడమ భుజం నుండి ఎడమ చేయి క్రిందికి జారితే.`, `அது அறுந்தால், விழுந்தால், அல்லது இடது தோளிலிருந்து இடது கைக்குக் கீழே நழுவினால்.`, `जब वह टूट जाए, गिर जाए, या बाएँ कंधे से बाएँ हाथ के नीचे खिसक जाए।`),
        L(`If you forget to loop it over the right ear while answering nature's call.`, `ಮಲಮೂತ್ರ ವಿಸರ್ಜನೆಯ ವೇಳೆ ಬಲ ಕಿವಿಗೆ ಸುತ್ತಲು ಮರೆತರೆ.`, `మలమూత్ర విసర్జన సమయంలో కుడి చెవికి చుట్టడం మరచిపోతే.`, `மலஜலம் கழிக்கும்போது வலது காதில் சுற்ற மறந்தால்.`, `मल-मूत्र त्याग के समय दाहिने कान पर लपेटना भूल जाएँ तो।`),
        L(`When it becomes soiled, and otherwise every four months even if intact.`, `ಮಲಿನವಾದಾಗ; ಇಲ್ಲದಿದ್ದರೂ ಪ್ರತಿ ನಾಲ್ಕು ತಿಂಗಳಿಗೊಮ್ಮೆ.`, `మలినమైనప్పుడు; లేకున్నా ప్రతి నాలుగు నెలలకు ఒకసారి.`, `அழுக்கானால்; இல்லையெனினும் நான்கு மாதத்துக்கு ஒருமுறை.`, `मलिन होने पर; अन्यथा भी हर चार महीने में।`)
      ] }
  ]
};
